import { createSlice, createAsyncThunk, PayloadAction } from '@reduxjs/toolkit'
import { MediaFile } from '../../services/mediaFileService'
import MediaFileServiceInstance from '../../services/mediaFileService'
import MediaScannerService from '../../services/mediaScannerService'
import { unifiedMediaApi } from '../api/unifiedMediaApi'

// 异步操作：扫描目录
export const scanDirectory = createAsyncThunk(
  'mediaFiles/scanDirectory',
  async (directoryPath: string) => {
    const result = await MediaFileServiceInstance.scanDirectory(directoryPath)
    if (!result.success) {
      throw new Error(result.error || '扫描目录失败')
    }
    return result.files
  }
)

// 异步操作：扫描所有媒体文件目录
export const scanAllMediaDirectories = createAsyncThunk(
  'mediaFiles/scanAllMediaDirectories',
  async () => {
    try {
      // 使用统一媒体API获取所有媒体文件
      const files = await unifiedMediaApi.getAllMediaFiles()
      return files
    } catch (error) {
      // 如果统一API失败，回退到原始方法
      console.warn('统一媒体API失败，回退到原始扫描方法:', error)
      const files = await MediaScannerService.scanAllMediaDirectories()
      return files
    }
  }
)

// 异步操作：扫描特定类型的媒体文件目录
export const scanMediaDirectory = createAsyncThunk(
  'mediaFiles/scanMediaDirectory',
  async (type: 'image' | 'video' | 'audio', { rejectWithValue }) => {
    console.log(`scanMediaDirectory被调用，类型: ${type}`);
    try {
      // 使用统一媒体API获取特定类型的媒体文件
      console.log('尝试使用统一媒体API获取媒体文件...');
      const files = await unifiedMediaApi.getMediaFilesByType(type);
      console.log(`从统一媒体API获取到 ${files.length} 个${type}文件`);
      return { files, type };
    } catch (error) {
      // 如果统一API失败，回退到原始方法
      console.warn('统一媒体API失败，回退到原始扫描方法:', error);
      try {
        const files = await MediaScannerService.scanMediaDirectory(type);
        console.log(`从原始扫描方法获取到 ${files.length} 个${type}文件`);
        return { files, type };
      } catch (fallbackError) {
        console.error('原始扫描方法也失败:', fallbackError);
        return rejectWithValue(fallbackError instanceof Error ? fallbackError.message : '扫描媒体文件失败');
      }
    }
  }
)

// 异步操作：从文件列表创建媒体文件
export const createMediaFilesFromFileList = createAsyncThunk(
  'mediaFiles/createMediaFilesFromFileList',
  async ({ fileList, directoryPath }: { fileList: FileList; directoryPath?: string }) => {
    const result = await MediaScannerService.createMediaFilesFromFileList(fileList, directoryPath)
    return result
  }
)

// 异步操作：获取媒体文件类别
export const fetchMediaCategories = createAsyncThunk(
  'mediaFiles/fetchMediaCategories',
  async () => {
    try {
      const categories = await unifiedMediaApi.getMediaCategories()
      return categories
    } catch (error) {
      console.warn('获取媒体文件类别失败:', error)
      return []
    }
  }
)

// 异步操作：获取媒体文件标签
export const fetchMediaTags = createAsyncThunk(
  'mediaFiles/fetchMediaTags',
  async () => {
    try {
      const tags = await unifiedMediaApi.getMediaTags()
      return tags
    } catch (error) {
      console.warn('获取媒体文件标签失败:', error)
      return []
    }
  }
)

// 异步操作：上传文件
export const uploadFilesAsync = createAsyncThunk(
  'mediaFiles/uploadFiles',
  async ({ files, directory }: { files: FileList, directory: 'images' | 'videos' | 'audios' }, { rejectWithValue }) => {
    try {
      const uploadedFiles = await MediaFileServiceInstance.uploadFiles(files, directory)
      return uploadedFiles
    } catch (error) {
      return rejectWithValue(error instanceof Error ? error.message : '上传文件失败')
    }
  }
)

// 状态接口
interface MediaFilesState {
  files: MediaFile[]
  filteredFiles: MediaFile[]
  loading: boolean
  error: string | null
  uploadStatus: 'idle' | 'loading' | 'success' | 'error'
  uploadError: string | null
  selectedType: 'all' | 'image' | 'video' | 'audio'
  selectedCategory: string
  selectedTag: string
  searchQuery: string
  categories: string[]
  tags: string[]
}

// 初始状态
const initialState: MediaFilesState = {
  files: [],
  filteredFiles: [],
  loading: false,
  error: null,
  uploadStatus: 'idle',
  uploadError: null,
  selectedType: 'all',
  selectedCategory: 'all',
  selectedTag: 'all',
  searchQuery: '',
  categories: [],
  tags: []
}

// 创建slice
const mediaFilesSlice = createSlice({
  name: 'mediaFiles',
  initialState,
  reducers: {
    // 设置文件列表
    setFiles: (state, action: PayloadAction<MediaFile[]>) => {
      state.files = action.payload
      state.categories = MediaFileServiceInstance.getCategories(action.payload)
      state.tags = MediaFileServiceInstance.getTags(action.payload)
      mediaFilesSlice.caseReducers.applyFilters(state)
    },
    
    // 添加文件
    addFiles: (state, action: PayloadAction<MediaFile[]>) => {
      state.files = [...state.files, ...action.payload]
      state.categories = MediaFileServiceInstance.getCategories(state.files)
      state.tags = MediaFileServiceInstance.getTags(state.files)
      mediaFilesSlice.caseReducers.applyFilters(state)
    },
    
    // 删除文件
    removeFile: (state, action: PayloadAction<string>) => {
      const fileId = action.payload
        state.files = state.files.filter((file: MediaFile) => file.id !== fileId)
        state.categories = MediaFileServiceInstance.getCategories(state.files)
        state.tags = MediaFileServiceInstance.getTags(state.files)
      mediaFilesSlice.caseReducers.applyFilters(state)
    },
    
    // 设置类型过滤器
    setTypeFilter: (state, action: PayloadAction<'all' | 'image' | 'video' | 'audio'>) => {
      state.selectedType = action.payload
      mediaFilesSlice.caseReducers.applyFilters(state)
    },
    
    // 设置分类过滤器
    setCategoryFilter: (state, action: PayloadAction<string>) => {
      state.selectedCategory = action.payload
      mediaFilesSlice.caseReducers.applyFilters(state)
    },
    
    // 设置标签过滤器
    setTagFilter: (state, action: PayloadAction<string>) => {
      state.selectedTag = action.payload
      mediaFilesSlice.caseReducers.applyFilters(state)
    },
    
    // 设置搜索查询
    setSearchQuery: (state, action: PayloadAction<string>) => {
      state.searchQuery = action.payload
      mediaFilesSlice.caseReducers.applyFilters(state)
    },
    
    // 清除所有过滤器
    clearFilters: (state) => {
      state.selectedType = 'all'
      state.selectedCategory = 'all'
      state.selectedTag = 'all'
      state.searchQuery = ''
      mediaFilesSlice.caseReducers.applyFilters(state)
    },
    
    // 应用过滤器
    applyFilters: (state) => {
      let filtered = [...state.files]
      
      // 应用类型过滤器
      if (state.selectedType !== 'all') {
        filtered = MediaFileServiceInstance.filterByType(filtered, state.selectedType)
      }
      
      // 应用分类过滤器
      if (state.selectedCategory !== 'all') {
        filtered = MediaFileServiceInstance.filterByCategory(filtered, state.selectedCategory)
      }
      
      // 应用标签过滤器
      if (state.selectedTag !== 'all') {
        filtered = MediaFileServiceInstance.filterByTag(filtered, state.selectedTag)
      }
      
      // 应用搜索查询
      if (state.searchQuery.trim() !== '') {
        const query = state.searchQuery.toLowerCase()
        filtered = filtered.filter(file => 
          file.name.toLowerCase().includes(query) ||
          (file.category && file.category.toLowerCase().includes(query)) ||
          file.tags.some((tag: string) => tag.toLowerCase().includes(query))
        )
      }
      
      state.filteredFiles = filtered
    },
    
    // 上传文件
    uploadFiles: (state) => {
      state.uploadStatus = 'loading'
      state.uploadError = null
    },
    
    // 上传文件成功
    uploadFilesSuccess: (state, action) => {
      state.uploadStatus = 'success'
      state.uploadError = null
      state.files = [...state.files, ...action.payload]
      state.categories = MediaFileServiceInstance.getCategories(state.files)
      state.tags = MediaFileServiceInstance.getTags(state.files)
      mediaFilesSlice.caseReducers.applyFilters(state)
    },
    
    // 上传文件失败
    uploadFilesFailure: (state, action) => {
      state.uploadStatus = 'error'
      state.uploadError = action.payload
    },
    
    // 清除错误
    clearError: (state) => {
      state.error = null
    }
  },
  extraReducers: (builder) => {
    // 扫描目录
    builder
      .addCase(scanDirectory.pending, (state) => {
        state.loading = true
        state.error = null
      })
      .addCase(scanDirectory.fulfilled, (state, action) => {
        state.loading = false
        state.files = action.payload
        state.categories = MediaFileServiceInstance.getCategories(action.payload)
        state.tags = MediaFileServiceInstance.getTags(action.payload)
        mediaFilesSlice.caseReducers.applyFilters(state)
      })
      .addCase(scanDirectory.rejected, (state, action) => {
        state.loading = false
        state.error = action.error.message || '扫描目录失败'
      })
    
    // 扫描所有媒体文件目录
    builder
      .addCase(scanAllMediaDirectories.pending, (state) => {
        state.loading = true
        state.error = null
      })
      .addCase(scanAllMediaDirectories.fulfilled, (state, action) => {
        state.loading = false
        state.files = action.payload
        state.categories = MediaFileServiceInstance.getCategories(action.payload)
        state.tags = MediaFileServiceInstance.getTags(action.payload)
        mediaFilesSlice.caseReducers.applyFilters(state)
      })
      .addCase(scanAllMediaDirectories.rejected, (state, action) => {
        state.loading = false
        state.error = action.error.message || '扫描所有媒体文件失败'
      })
    
    // 扫描特定类型的媒体文件目录
    builder
      .addCase(scanMediaDirectory.pending, (state) => {
        state.loading = true
        state.error = null
      })
      .addCase(scanMediaDirectory.fulfilled, (state, action) => {
        state.loading = false
        const { files, type } = action.payload
        
        // 过滤掉相同类型的现有文件
        const existingFiles = state.files.filter(file => file.type !== type)
        state.files = [...existingFiles, ...files]
        
        state.categories = MediaFileServiceInstance.getCategories(state.files)
        state.tags = MediaFileServiceInstance.getTags(state.files)
        mediaFilesSlice.caseReducers.applyFilters(state)
      })
      .addCase(scanMediaDirectory.rejected, (state, action) => {
        state.loading = false
        state.error = action.error.message || '扫描媒体文件失败'
      })
    
    // 从文件列表创建媒体文件
    builder
      .addCase(createMediaFilesFromFileList.pending, (state) => {
        state.loading = true
        state.error = null
      })
      .addCase(createMediaFilesFromFileList.fulfilled, (state, action) => {
        state.loading = false
        const existingFileIds = new Set(state.files.map(file => file.id))
        const newFiles = action.payload.filter((file: MediaFile) => !existingFileIds.has(file.id))
        state.files = [...state.files, ...newFiles]
          state.categories = MediaFileServiceInstance.getCategories(state.files)
          state.tags = MediaFileServiceInstance.getTags(state.files)
        mediaFilesSlice.caseReducers.applyFilters(state)
      })
      .addCase(createMediaFilesFromFileList.rejected, (state, action) => {
        state.loading = false
        state.error = action.error.message || '处理文件失败'
      })
    
    // 上传文件
    builder
      .addCase(uploadFilesAsync.pending, (state) => {
        state.loading = true
        state.error = null
      })
      .addCase(uploadFilesAsync.fulfilled, (state, action) => {
        state.loading = false
        state.files = [...state.files, ...action.payload]
        state.categories = MediaFileServiceInstance.getCategories(state.files)
        state.tags = MediaFileServiceInstance.getTags(state.files)
        mediaFilesSlice.caseReducers.applyFilters(state)
      })
      .addCase(uploadFilesAsync.rejected, (state, action) => {
        state.loading = false
        state.error = action.payload as string
      })
    
    // 获取媒体文件类别
    builder
      .addCase(fetchMediaCategories.pending, (state) => {
        state.loading = true
        state.error = null
      })
      .addCase(fetchMediaCategories.fulfilled, (state, action) => {
        state.loading = false
        state.categories = action.payload
      })
      .addCase(fetchMediaCategories.rejected, (state, action) => {
        state.loading = false
        state.error = action.error.message || '获取媒体文件类别失败'
      })
    
    // 获取媒体文件标签
    builder
      .addCase(fetchMediaTags.pending, (state) => {
        state.loading = true
        state.error = null
      })
      .addCase(fetchMediaTags.fulfilled, (state, action) => {
        state.loading = false
        state.tags = action.payload
      })
      .addCase(fetchMediaTags.rejected, (state, action) => {
        state.loading = false
        state.error = action.error.message || '获取媒体文件标签失败'
      })
  }
})

// 导出actions
export const {
  setFiles,
  addFiles,
  removeFile,
  setTypeFilter,
  setCategoryFilter,
  setTagFilter,
  setSearchQuery,
  clearFilters,
  clearError
} = mediaFilesSlice.actions

// 导出reducer
export default mediaFilesSlice.reducer

// 选择器
export const selectMediaFiles = (state: { mediaFiles: MediaFilesState }) => state.mediaFiles.files
export const selectFilteredMediaFiles = (state: { mediaFiles: MediaFilesState }) => state.mediaFiles.filteredFiles
export const selectMediaFilesLoading = (state: { mediaFiles: MediaFilesState }) => state.mediaFiles.loading
export const selectMediaFilesError = (state: { mediaFiles: MediaFilesState }) => state.mediaFiles.error
export const selectMediaFilesCategories = (state: { mediaFiles: MediaFilesState }) => state.mediaFiles.categories
export const selectMediaFilesTags = (state: { mediaFiles: MediaFilesState }) => state.mediaFiles.tags
export const selectMediaFilesFilters = (state: { mediaFiles: MediaFilesState }) => ({
  type: state.mediaFiles.selectedType,
  category: state.mediaFiles.selectedCategory,
  tag: state.mediaFiles.selectedTag,
  searchQuery: state.mediaFiles.searchQuery
})