// 媒体文件配置
// 简化版本：直接使用打包后的媒体文件，不再使用GitHub Releases和CDN

// 定义配置类型
interface MediaConfig {
  basePath: string;
}

export const MEDIA_CONFIG = {
  // 所有环境都使用相同的配置
  basePath: '/media'
} as MediaConfig;

// 获取媒体文件URL的函数
export function getMediaUrl(filePath: string): string {
  // 直接返回相对路径
  return `${MEDIA_CONFIG.basePath}/${filePath}`;
}

// 需要特殊处理的文件类型（保留用于可能的未来扩展）
export const MEDIA_FILE_TYPES = [
  '.mp4', '.mov', '.avi', '.mkv',  // 视频
  '.flac', '.mp3', '.wav', '.aac',  // 音频
  '.psd', '.ai', '.sketch', '.fig', // 设计文件
];

// 检查文件是否是媒体文件
export function isMediaFile(filePath: string): boolean {
  const ext = filePath.toLowerCase().substring(filePath.lastIndexOf('.'));
  return MEDIA_FILE_TYPES.includes(ext);
}