import React from 'react'
import { useSelector } from 'react-redux'
import { User } from '../types/user'
import { RootState } from '../store'

// 定义权限枚举
export enum Permission {
  // 博客相关权限
  READ_BLOG = 'read_blog',
  WRITE_BLOG = 'write_blog',
  EDIT_OWN_BLOG = 'edit_own_blog',
  EDIT_ANY_BLOG = 'edit_any_blog',
  DELETE_OWN_BLOG = 'delete_own_blog',
  DELETE_ANY_BLOG = 'delete_any_blog',
  PUBLISH_BLOG = 'publish_blog',
  
  // 评论相关权限
  READ_COMMENT = 'read_comment',
  WRITE_COMMENT = 'write_comment',
  EDIT_OWN_COMMENT = 'edit_own_comment',
  EDIT_ANY_COMMENT = 'edit_any_comment',
  DELETE_OWN_COMMENT = 'delete_own_comment',
  DELETE_ANY_COMMENT = 'delete_any_comment',
  MODERATE_COMMENT = 'moderate_comment',
  
  // 用户相关权限
  READ_USER_PROFILE = 'read_user_profile',
  EDIT_OWN_PROFILE = 'edit_own_profile',
  EDIT_ANY_PROFILE = 'edit_any_profile',
  DELETE_USER = 'delete_user',
  MANAGE_USERS = 'manage_users',
  
  // 系统管理权限
  ACCESS_ADMIN = 'access_admin',
  MANAGE_SYSTEM = 'manage_system',
  VIEW_ANALYTICS = 'view_analytics',
}

// 定义角色枚举
export enum Role {
  ADMIN = 'admin',
  AUTHOR = 'author',
  USER = 'user',
  GUEST = 'guest',
}

// 角色权限映射
export const ROLE_PERMISSIONS: Record<Role, Permission[]> = {
  [Role.ADMIN]: [
    // 管理员拥有所有权限
    Permission.READ_BLOG,
    Permission.WRITE_BLOG,
    Permission.EDIT_OWN_BLOG,
    Permission.EDIT_ANY_BLOG,
    Permission.DELETE_OWN_BLOG,
    Permission.DELETE_ANY_BLOG,
    Permission.PUBLISH_BLOG,
    Permission.READ_COMMENT,
    Permission.WRITE_COMMENT,
    Permission.EDIT_OWN_COMMENT,
    Permission.EDIT_ANY_COMMENT,
    Permission.DELETE_OWN_COMMENT,
    Permission.DELETE_ANY_COMMENT,
    Permission.MODERATE_COMMENT,
    Permission.READ_USER_PROFILE,
    Permission.EDIT_OWN_PROFILE,
    Permission.EDIT_ANY_PROFILE,
    Permission.DELETE_USER,
    Permission.MANAGE_USERS,
    Permission.ACCESS_ADMIN,
    Permission.MANAGE_SYSTEM,
    Permission.VIEW_ANALYTICS,
  ],
  [Role.AUTHOR]: [
    // 作者可以创建、编辑和发布自己的博客，管理评论
    Permission.READ_BLOG,
    Permission.WRITE_BLOG,
    Permission.EDIT_OWN_BLOG,
    Permission.DELETE_OWN_BLOG,
    Permission.PUBLISH_BLOG,
    Permission.READ_COMMENT,
    Permission.WRITE_COMMENT,
    Permission.EDIT_OWN_COMMENT,
    Permission.DELETE_OWN_COMMENT,
    Permission.READ_USER_PROFILE,
    Permission.EDIT_OWN_PROFILE,
  ],
  [Role.USER]: [
    // 普通用户可以阅读博客和评论，发表评论
    Permission.READ_BLOG,
    Permission.READ_COMMENT,
    Permission.WRITE_COMMENT,
    Permission.EDIT_OWN_COMMENT,
    Permission.DELETE_OWN_COMMENT,
    Permission.READ_USER_PROFILE,
    Permission.EDIT_OWN_PROFILE,
  ],
  [Role.GUEST]: [
    // 访客只能阅读
    Permission.READ_BLOG,
    Permission.READ_COMMENT,
    Permission.READ_USER_PROFILE,
  ],
}

// 获取用户角色
export const getUserRole = (user: User | null): Role => {
  if (!user) return Role.GUEST
  return (user.role as Role) || Role.USER
}

// 检查用户是否有特定权限
export const hasPermission = (user: User | null, permission: Permission): boolean => {
  const userRole = getUserRole(user)
  
  // 如果用户有自定义权限，先检查自定义权限
  if (user?.permissions && user.permissions.includes(permission)) {
    return true
  }
  
  // 否则检查角色默认权限
  const rolePermissions = ROLE_PERMISSIONS[userRole]
  return rolePermissions.includes(permission)
}

// 检查用户是否有多个权限中的任意一个
export const hasAnyPermission = (user: User | null, permissions: Permission[]): boolean => {
  return permissions.some(permission => hasPermission(user, permission))
}

// 检查用户是否拥有所有指定权限
export const hasAllPermissions = (user: User | null, permissions: Permission[]): boolean => {
  return permissions.every(permission => hasPermission(user, permission))
}

// 检查用户是否可以编辑特定资源
export const canEditResource = (user: User | null, resourceAuthorId: string): boolean => {
  // 如果用户有编辑任何资源的权限，直接返回true
  if (hasPermission(user, Permission.EDIT_ANY_BLOG) || 
      hasPermission(user, Permission.EDIT_ANY_COMMENT) || 
      hasPermission(user, Permission.EDIT_ANY_PROFILE)) {
    return true
  }
  
  // 否则检查是否是资源作者且有编辑自己资源的权限
  return user?.id === resourceAuthorId && 
         (hasPermission(user, Permission.EDIT_OWN_BLOG) || 
          hasPermission(user, Permission.EDIT_OWN_COMMENT) || 
          hasPermission(user, Permission.EDIT_OWN_PROFILE))
}

// 检查用户是否可以删除特定资源
export const canDeleteResource = (user: User | null, resourceAuthorId: string): boolean => {
  // 如果用户有删除任何资源的权限，直接返回true
  if (hasPermission(user, Permission.DELETE_ANY_BLOG) || 
      hasPermission(user, Permission.DELETE_ANY_COMMENT)) {
    return true
  }
  
  // 否则检查是否是资源作者且有删除自己资源的权限
  return user?.id === resourceAuthorId && 
         (hasPermission(user, Permission.DELETE_OWN_BLOG) || 
          hasPermission(user, Permission.DELETE_OWN_COMMENT))
}

// 获取用户所有权限
export const getUserPermissions = (user: User | null): Permission[] => {
  const userRole = getUserRole(user)
  const rolePermissions = ROLE_PERMISSIONS[userRole]
  
  // 合并角色权限和自定义权限
  const customPermissions = user?.permissions || []
  return [...new Set([...rolePermissions, ...customPermissions])] as Permission[]
}

// 权限装饰器函数，用于保护组件
export const withPermissionCheck = (
  Component: React.ComponentType<any>,
  requiredPermissions: Permission | Permission[],
  fallbackComponent?: React.ComponentType<any>
) => {
  return function ProtectedComponent(props: any) {
    const { user } = useSelector((state: RootState) => state.auth)
    
    const hasRequiredPermission = Array.isArray(requiredPermissions)
      ? hasAnyPermission(user, requiredPermissions)
      : hasPermission(user, requiredPermissions)
    
    if (!hasRequiredPermission) {
      return fallbackComponent ? React.createElement(fallbackComponent) : <div>无权访问</div>
    }
    
    return <Component {...props} />
  }
}