import React, { useState, useEffect } from 'react';
import { Box, Typography, List, ListItem, Button, Alert } from '@mui/material';
import { useMediaFiles, MediaFileWithId } from '../../store/api/unifiedMediaApi';

const AudioTestPage: React.FC = () => {
  const [testResults, setTestResults] = useState<{fileName: string, url: string, status: string, error?: string}[]>([]);
  const [isTesting, setIsTesting] = useState(false);
  
  // 使用新的媒体文件API
  const { files: audioFiles, loading, error } = useMediaFiles({ type: 'audio' });

  const testAudioFile = async (audioFile: MediaFileWithId): Promise<{fileName: string, url: string, status: string, error?: string}> => {
    const { name: fileName, url } = audioFile;
    
    try {
      // 尝试获取文件头信息
      const response = await fetch(url, { method: 'HEAD' });
      
      if (response.ok) {
        // 尝试创建音频元素
        const audio = new Audio();
        
        return new Promise((resolve) => {
          audio.src = url;
          
          audio.addEventListener('canplay', () => {
            resolve({
              fileName,
              url,
              status: '成功',
            });
          });
          
          audio.addEventListener('error', (e) => {
            const audioError = audio.error;
            resolve({
              fileName,
              url,
              status: '失败',
              error: `音频错误: ${audioError?.message || '未知错误'} (代码: ${audioError?.code})`,
            });
          });
          
          // 设置超时
          setTimeout(() => {
            resolve({
              fileName,
              url,
              status: '超时',
              error: '加载超时',
            });
          }, 5000);
          
          audio.load();
        });
      } else {
        return {
          fileName,
          url,
          status: '失败',
          error: `HTTP错误: ${response.status} ${response.statusText}`,
        };
      }
    } catch (error) {
      return {
        fileName,
        url,
        status: '失败',
        error: error instanceof Error ? error.message : String(error),
      };
    }
  };

  const testAllAudioFiles = async () => {
    setIsTesting(true);
    setTestResults([]);
    
    if (!audioFiles || audioFiles.length === 0) {
      setIsTesting(false);
      return;
    }
    
    const results = [];
    for (const audioFile of audioFiles) {
      const result = await testAudioFile(audioFile);
      results.push(result);
      setTestResults([...results]);
    }
    
    setIsTesting(false);
  };

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" gutterBottom>
        音频文件加载测试
      </Typography>
      
      {loading && <Typography>正在加载音频文件列表...</Typography>}
      {error && <Alert severity="error" sx={{ mb: 2 }}>加载音频文件失败: {error}</Alert>}
      
      <Button 
        variant="contained" 
        onClick={testAllAudioFiles} 
        disabled={isTesting || loading || !audioFiles || audioFiles.length === 0}
        sx={{ mb: 3 }}
      >
        {isTesting ? '测试中...' : '测试所有音频文件'}
      </Button>
      
      {audioFiles && audioFiles.length > 0 && (
        <Typography variant="body2" sx={{ mb: 2 }}>
          找到 {audioFiles.length} 个音频文件
        </Typography>
      )}
      
      {testResults.length > 0 && (
        <Box sx={{ mt: 3 }}>
          <Typography variant="h6" gutterBottom>
            测试结果:
          </Typography>
          
          <List>
            {testResults.map((result, index) => (
              <ListItem key={index} sx={{ flexDirection: 'column', alignItems: 'flex-start', py: 1 }}>
                <Typography variant="body1" fontWeight="bold">
                  {result.fileName}
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  URL: {result.url}
                </Typography>
                <Alert 
                  severity={result.status === '成功' ? 'success' : 'error'} 
                  sx={{ mt: 1, width: '100%' }}
                >
                  状态: {result.status}
                  {result.error && ` - ${result.error}`}
                </Alert>
              </ListItem>
            ))}
          </List>
        </Box>
      )}
    </Box>
  );
};

export default AudioTestPage;