import { createApi, fetchBaseQuery } from '@reduxjs/toolkit/query/react'
import type { RootState } from '../index'

// 定义AI相关类型
export interface AIArticle {
  id: string
  title: string
  content: string
  excerpt: string
  author: {
    id: string
    name: string
    avatar?: string
  }
  category: string
  tags: string[]
  coverImage?: string
  createdAt: string
  updatedAt: string
  viewCount: number
  likeCount: number
  commentCount: number
  isPublished: boolean
}

export interface AIModel {
  id: string
  name: string
  description: string
  version: string
  type: 'language' | 'vision' | 'audio' | 'multimodal'
  framework: string
  parameters: {
    size: string
    trainingData: string
    accuracy?: number
    performance?: string
  }
  documentation: string
  repository?: string
  demoUrl?: string
  createdAt: string
  updatedAt: string
}

export interface AIExperiment {
  id: string
  title: string
  description: string
  modelId: string
  model: AIModel
  dataset: string
  methodology: string
  results: {
    metrics: Record<string, number>
    charts: string[]
    summary: string
  }
  conclusion: string
  author: {
    id: string
    name: string
    avatar?: string
  }
  createdAt: string
  updatedAt: string
}

export interface AITool {
  id: string
  name: string
  description: string
  category: string
  tags: string[]
  website: string
  pricing: 'free' | 'freemium' | 'paid'
  features: string[]
  screenshot?: string
  rating: number
  reviewCount: number
  author: {
    id: string
    name: string
    avatar?: string
  }
  createdAt: string
  updatedAt: string
}

export interface AIProject {
  id: string
  title: string
  description: string
  technologies: string[]
  githubUrl?: string
  demoUrl?: string
  images: string[]
  author: {
    id: string
    name: string
    avatar?: string
  }
  createdAt: string
  updatedAt: string
}

export interface AIArticleListResponse {
  articles: AIArticle[]
  pagination: {
    page: number
    limit: number
    total: number
    totalPages: number
  }
}

export interface AIModelListResponse {
  models: AIModel[]
  pagination: {
    page: number
    limit: number
    total: number
    totalPages: number
  }
}

export interface AIExperimentListResponse {
  experiments: AIExperiment[]
  pagination: {
    page: number
    limit: number
    total: number
    totalPages: number
  }
}

export interface AIToolListResponse {
  tools: AITool[]
  pagination: {
    page: number
    limit: number
    total: number
    totalPages: number
  }
}

export interface AIProjectListResponse {
  projects: AIProject[]
  pagination: {
    page: number
    limit: number
    total: number
    totalPages: number
  }
}

export interface AIQueryParams {
  page?: number
  limit?: number
  category?: string
  tag?: string
  search?: string
  sortBy?: 'createdAt' | 'updatedAt' | 'viewCount' | 'likeCount' | 'rating'
  sortOrder?: 'asc' | 'desc'
}

export const aiApi = createApi({
  reducerPath: 'aiApi',
  baseQuery: fetchBaseQuery({
    baseUrl: '/api/v1/ai',
    prepareHeaders: (headers, { getState }) => {
      const token = (getState() as RootState).auth.token
      if (token) {
        headers.set('authorization', `Bearer ${token}`)
      }
      return headers
    },
  }),
  tagTypes: ['AIArticle', 'AIModel', 'AIExperiment', 'AITool', 'AIProject'],
  endpoints: (builder) => ({
    // AI文章相关
    getAIArticles: builder.query<AIArticleListResponse, AIQueryParams>({
      query: (params) => ({
        url: '/articles',
        params,
      }),
      providesTags: ['AIArticle'],
    }),
    getAIArticleById: builder.query<AIArticle, string>({
      query: (id) => `/articles/${id}`,
      providesTags: (_result, _error, id) => [{ type: 'AIArticle', id }],
    }),
    createAIArticle: builder.mutation<AIArticle, Partial<AIArticle> & Pick<AIArticle, 'title' | 'content'>>({
      query: (article) => ({
        url: '/articles',
        method: 'POST',
        body: article,
      }),
      invalidatesTags: ['AIArticle'],
    }),
    updateAIArticle: builder.mutation<AIArticle, { id: string; data: Partial<AIArticle> }>({
      query: ({ id, data }) => ({
        url: `/articles/${id}`,
        method: 'PUT',
        body: data,
      }),
      invalidatesTags: (_result, _error, { id }) => [{ type: 'AIArticle', id }],
    }),
    deleteAIArticle: builder.mutation<void, string>({
      query: (id) => ({
        url: `/articles/${id}`,
        method: 'DELETE',
      }),
      invalidatesTags: ['AIArticle'],
    }),
    // AI模型相关
    getAIModels: builder.query<AIModelListResponse, AIQueryParams>({
      query: (params) => ({
        url: '/models',
        params,
      }),
      providesTags: ['AIModel'],
    }),
    getAIModelById: builder.query<AIModel, string>({
      query: (id) => `/models/${id}`,
      providesTags: (_result, _error, id) => [{ type: 'AIModel', id }],
    }),
    createAIModel: builder.mutation<AIModel, Partial<AIModel> & Pick<AIModel, 'name' | 'description' | 'type' | 'framework'>>({
      query: (model) => ({
        url: '/models',
        method: 'POST',
        body: model,
      }),
      invalidatesTags: ['AIModel'],
    }),
    updateAIModel: builder.mutation<AIModel, { id: string; data: Partial<AIModel> }>({
      query: ({ id, data }) => ({
        url: `/models/${id}`,
        method: 'PUT',
        body: data,
      }),
      invalidatesTags: (_result, _error, { id }) => [{ type: 'AIModel', id }],
    }),
    deleteAIModel: builder.mutation<void, string>({
      query: (id) => ({
        url: `/models/${id}`,
        method: 'DELETE',
      }),
      invalidatesTags: ['AIModel'],
    }),
    // AI实验相关
    getAIExperiments: builder.query<AIExperimentListResponse, AIQueryParams>({
      query: (params) => ({
        url: '/experiments',
        params,
      }),
      providesTags: ['AIExperiment'],
    }),
    getAIExperimentById: builder.query<AIExperiment, string>({
      query: (id) => `/experiments/${id}`,
      providesTags: (_result, _error, id) => [{ type: 'AIExperiment', id }],
    }),
    createAIExperiment: builder.mutation<AIExperiment, Partial<AIExperiment> & Pick<AIExperiment, 'title' | 'description' | 'modelId'>>({
      query: (experiment) => ({
        url: '/experiments',
        method: 'POST',
        body: experiment,
      }),
      invalidatesTags: ['AIExperiment'],
    }),
    updateAIExperiment: builder.mutation<AIExperiment, { id: string; data: Partial<AIExperiment> }>({
      query: ({ id, data }) => ({
        url: `/experiments/${id}`,
        method: 'PUT',
        body: data,
      }),
      invalidatesTags: (_result, _error, { id }) => [{ type: 'AIExperiment', id }],
    }),
    deleteAIExperiment: builder.mutation<void, string>({
      query: (id) => ({
        url: `/experiments/${id}`,
        method: 'DELETE',
      }),
      invalidatesTags: ['AIExperiment'],
    }),
    // AI工具相关
    getAITools: builder.query<AIToolListResponse, AIQueryParams>({
      query: (params) => ({
        url: '/tools',
        params,
      }),
      providesTags: ['AITool'],
    }),
    getAIToolById: builder.query<AITool, string>({
      query: (id) => `/tools/${id}`,
      providesTags: (_result, _error, id) => [{ type: 'AITool', id }],
    }),
    createAITool: builder.mutation<AITool, Partial<AITool> & Pick<AITool, 'name' | 'description' | 'category' | 'website'>>({
      query: (tool) => ({
        url: '/tools',
        method: 'POST',
        body: tool,
      }),
      invalidatesTags: ['AITool'],
    }),
    updateAITool: builder.mutation<AITool, { id: string; data: Partial<AITool> }>({
      query: ({ id, data }) => ({
        url: `/tools/${id}`,
        method: 'PUT',
        body: data,
      }),
      invalidatesTags: (_result, _error, { id }) => [{ type: 'AITool', id }],
    }),
    deleteAITool: builder.mutation<void, string>({
      query: (id) => ({
        url: `/tools/${id}`,
        method: 'DELETE',
      }),
      invalidatesTags: ['AITool'],
    }),
    // AI项目相关
    getAIProjects: builder.query<AIProjectListResponse, AIQueryParams>({
      query: (params) => ({
        url: '/projects',
        params,
      }),
      providesTags: ['AIProject'],
    }),
    getAIProjectById: builder.query<AIProject, string>({
      query: (id) => `/projects/${id}`,
      providesTags: (_result, _error, id) => [{ type: 'AIProject', id }],
    }),
    createAIProject: builder.mutation<AIProject, Partial<AIProject> & Pick<AIProject, 'title' | 'description' | 'technologies'>>({
      query: (project) => ({
        url: '/projects',
        method: 'POST',
        body: project,
      }),
      invalidatesTags: ['AIProject'],
    }),
    updateAIProject: builder.mutation<AIProject, { id: string; data: Partial<AIProject> }>({
      query: ({ id, data }) => ({
        url: `/projects/${id}`,
        method: 'PUT',
        body: data,
      }),
      invalidatesTags: (_result, _error, { id }) => [{ type: 'AIProject', id }],
    }),
    deleteAIProject: builder.mutation<void, string>({
      query: (id) => ({
        url: `/projects/${id}`,
        method: 'DELETE',
      }),
      invalidatesTags: ['AIProject'],
    }),
  }),
})

export const {
  // AI文章相关
  useGetAIArticlesQuery,
  useGetAIArticleByIdQuery,
  useCreateAIArticleMutation,
  useUpdateAIArticleMutation,
  useDeleteAIArticleMutation,
  // AI模型相关
  useGetAIModelsQuery,
  useGetAIModelByIdQuery,
  useCreateAIModelMutation,
  useUpdateAIModelMutation,
  useDeleteAIModelMutation,
  // AI实验相关
  useGetAIExperimentsQuery,
  useGetAIExperimentByIdQuery,
  useCreateAIExperimentMutation,
  useUpdateAIExperimentMutation,
  useDeleteAIExperimentMutation,
  // AI工具相关
  useGetAIToolsQuery,
  useGetAIToolByIdQuery,
  useCreateAIToolMutation,
  useUpdateAIToolMutation,
  useDeleteAIToolMutation,
  // AI项目相关
  useGetAIProjectsQuery,
  useGetAIProjectByIdQuery,
  useCreateAIProjectMutation,
  useUpdateAIProjectMutation,
  useDeleteAIProjectMutation,
} = aiApi