const categories = ['全部', '前端开发', '后端开发', '移动开发', '数据库', '人工智能']
const sortOptions = ['最新发布', '最多浏览', '最多点赞']

const Experience = () => {
  const [posts, setPosts] = useState(mockExperiencePosts)
  const [loading, setLoading] = useState(false)
  const [page, setPage] = useState(1)
  const [category, setCategory] = useState('全部')
  const [sortBy, setSortBy] = useState('最新发布')
  const [error] = useState('')
  
  const postsPerPage = 6
  const { isAuthenticated } = useSelector((state: RootState) => state.auth)

  useEffect(() => {
    // 模拟数据获取
    setLoading(true)
    setTimeout(() => {
      // 这里可以根据分类和排序选项过滤和排序数据
      let filteredPosts = [...mockExperiencePosts]
      
      if (category !== '全部') {
        filteredPosts = filteredPosts.filter(post => post.category === category)
      }
      
      if (sortBy === '最多浏览') {
        filteredPosts.sort((a, b) => b.viewCount - a.viewCount)
      } else if (sortBy === '最多点赞') {
        filteredPosts.sort((a, b) => b.likeCount - a.likeCount)
      }
      
      setPosts(filteredPosts)
      setLoading(false)
    }, 500)
  }, [category, sortBy])

  const handlePageChange = (_event: React.ChangeEvent<unknown>, value: number) => {
    setPage(value)
  }

  const handleCategoryChange = (event: any) => {
    setCategory(event.target.value)
    setPage(1)
  }

  const handleSortChange = (event: any) => {
    setSortBy(event.target.value)
    setPage(1)
  }

  const indexOfLastPost = page * postsPerPage
  const indexOfFirstPost = indexOfLastPost - postsPerPage
  const currentPosts = posts.slice(indexOfFirstPost, indexOfLastPost)
  const totalPages = Math.ceil(posts.length / postsPerPage)

  return (
    <Container maxWidth="lg" sx={{ py: 4 }}>
      <Box sx={{ mb: 4 }}>
        <Typography variant="h3" component="h1" gutterBottom>
          经验积累
        </Typography>
        <Typography variant="h6" color="text.secondary">
          分享项目经验，记录成长历程
        </Typography>
      </Box>

      {isAuthenticated && (
        <Box sx={{ mb: 3, display: 'flex', justifyContent: 'flex-end' }}>
          <Button variant="contained" href="/experience/create">
            分享经验
          </Button>
        </Box>
      )}

      <Paper sx={{ p: 2, mb: 3 }}>
        <Grid container spacing={2} alignItems="center">
        <Grid size={{ xs: 12, sm: 6, md: 3 }}>
            <FormControl fullWidth variant="outlined" size="small">
              <InputLabel>分类</InputLabel>
              <Select
                value={category}
                onChange={handleCategoryChange}
                label="分类"
              >
                {categories.map((cat) => (
                  <MenuItem key={cat} value={cat}>
                    {cat}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
          <Grid size={{ xs: 12, sm: 6, md: 3 }}>
            <FormControl fullWidth variant="outlined" size="small">
              <InputLabel>排序</InputLabel>
              <Select
                value={sortBy}
                onChange={handleSortChange}
                label="排序"
              >
                {sortOptions.map((option) => (
                  <MenuItem key={option} value={option}>
                    {option}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
        </Grid>
      </Paper>

      {loading ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
          <CircularProgress />
        </Box>
      ) : error ? (
        <Alert severity="error" sx={{ mb: 3 }}>
          {error}
        </Alert>
      ) : (
        <>
          <Grid container spacing={3}>
            {currentPosts.map((post) => (
              <Grid size={{ xs: 12, md: 6 }} key={post.id}>
                <Card sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
                  <CardContent sx={{ flexGrow: 1 }}>
                    <Typography variant="h5" component="h2" gutterBottom>
                      {post.title}
                    </Typography>
                    <Typography variant="body2" color="text.secondary" paragraph>
                      {post.summary}
                    </Typography>
                    <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5, mb: 2 }}>
                      {post.tags.map((tag) => (
                        <Chip key={tag} label={tag} size="small" variant="outlined" />
                      ))}
                    </Box>
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                      <Box sx={{ display: 'flex', alignItems: 'center' }}>
                        <Avatar sx={{ width: 24, height: 24, mr: 1 }}>
                          {post.author.name.charAt(0)}
                        </Avatar>
                        <Typography variant="body2">
                          {post.author.name}
                        </Typography>
                      </Box>
                      <Box sx={{ display: 'flex', alignItems: 'center', color: 'text.secondary' }}>
                        <CalendarToday sx={{ fontSize: 16, mr: 0.5 }} />
                        <Typography variant="body2">
                          {post.createdAt}
                        </Typography>
                      </Box>
                    </Box>
                    <Divider sx={{ my: 1.5 }} />
                    <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                      <Box sx={{ display: 'flex', gap: 2 }}>
                        <Box sx={{ display: 'flex', alignItems: 'center' }}>
                          <Visibility sx={{ fontSize: 16, mr: 0.5 }} />
                          <Typography variant="body2">{post.viewCount}</Typography>
                        </Box>
                        <Box sx={{ display: 'flex', alignItems: 'center' }}>
                          <ThumbUp sx={{ fontSize: 16, mr: 0.5 }} />
                          <Typography variant="body2">{post.likeCount}</Typography>
                        </Box>
                        <Box sx={{ display: 'flex', alignItems: 'center' }}>
                          <Comment sx={{ fontSize: 16, mr: 0.5 }} />
                          <Typography variant="body2">{post.commentCount}</Typography>
                        </Box>
                      </Box>
                      <Button size="small" href={`/experience/${post.id}`}>
                        查看详情
                      </Button>
                    </Box>
                  </CardContent>
                </Card>
              </Grid>
            ))}
          </Grid>

          {totalPages > 1 && (
            <Box sx={{ display: 'flex', justifyContent: 'center', mt: 4 }}>
              <Pagination
                count={totalPages}
                page={page}
                onChange={handlePageChange}
                color="primary"
              />
            </Box>
          )}
        </>
      )}
    </Container>
  )
}

export default Experience