import { createBrowserRouter } from 'react-router-dom'
import MainLayout from '../components/layout/MainLayout'
import Home from '../pages/Home/Home'
import Blog from '../pages/Blog/Blog'
import BlogPost from '../pages/Blog/BlogPost'
import BlogEditor from '../pages/Blog/BlogEditor'
import Experience from '../pages/Experience/Experience'
import Life from '../pages/Life/Life'
import AI from '../pages/AI/AI'
import Tutorial from '../pages/Tutorial/Tutorial'
import Essay from '../pages/Essay/Essay'
import Notes from '../pages/Notes/Notes'
import Login from '../pages/Login/Login'
import Register from '../pages/Register/Register'
import Profile from '../pages/Profile/Profile'
import Entertainment from '../pages/Entertainment'
import PhotoWall from '../pages/Entertainment/PhotoWall'
import MediaLibrary from '../pages/Entertainment/MediaLibrary'
import Music from '../pages/Entertainment/Music'
import AudioTest from '../pages/AudioTest'
import NotFound from '../pages/NotFound/NotFound'
import Unauthorized from '../pages/Error/Unauthorized'

// 路由守卫组件
import { ProtectedRoute } from '../components/auth/ProtectedRoute'
import { Permission } from '../utils/permissions'

const router = createBrowserRouter([
  {
    path: '/',
    element: <MainLayout />,
    children: [
      {
        index: true,
        element: <Home />
      },
      {
        path: 'blog',
        element: <Blog />
      },
      {
        path: 'blog/:slug',
        element: <BlogPost />
      },
      {
        path: 'experience',
        element: <Experience />
      },
      {
        path: 'life',
        element: <Life />
      },
      {
        path: 'ai',
        element: <AI />
      },
      {
        path: 'tutorial',
        element: <Tutorial />
      },
      {
        path: 'essay',
        element: <Essay />
      },
      {
        path: 'notes',
        element: <Notes />
      },
      {
        path: 'entertainment',
        element: <Entertainment />
      },
      {
        path: 'entertainment/PhotoWall',
        element: <PhotoWall />
      },
      {
        path: 'entertainment/PhotoWall/:category',
        element: <PhotoWall />
      },
      {
        path: 'entertainment/MediaLibrary',
        element: <MediaLibrary />
      },
      {
        path: 'entertainment/MediaLibrary/:category',
        element: <MediaLibrary />
      },
      {
        path: 'entertainment/Music',
        element: <Music />
      },
      {
        path: 'entertainment/Music/:category',
        element: <Music />
      },
      {
        path: 'audio-test',
        element: <AudioTest />
      },
      {
        path: 'login',
        element: <Login />
      },
      {
        path: 'register',
        element: <Register />
      },
      {
        path: 'unauthorized',
        element: <Unauthorized />
      },
      {
        path: 'profile',
        element: (
          <ProtectedRoute requiredPermission={Permission.EDIT_OWN_PROFILE}>
            <Profile />
          </ProtectedRoute>
        )
      },
      {
        path: 'blog/create',
        element: (
          <ProtectedRoute requiredPermission={Permission.WRITE_BLOG}>
            <BlogEditor />
          </ProtectedRoute>
        )
      },
      {
        path: 'blog/edit/:slug',
        element: (
          <ProtectedRoute requiredPermission={Permission.EDIT_OWN_BLOG}>
            <BlogEditor />
          </ProtectedRoute>
        )
      }
    ]
  },
  {
    path: '*',
    element: <NotFound />
  }
])

export default router