/**
 * 统一媒体API - 模仿博客API的实现方式
 * 使用import.meta.glob动态加载媒体文件
 */

import React, { useState, useEffect } from 'react';
import { MediaFile, MediaType } from '../../types/media'
import { ErrorHandlerUtils, ErrorType } from '../../utils/errorHandler'

// 定义媒体文件接口
export interface MediaFileWithId extends MediaFile {
  id: string
}

// 媒体文件统计信息
export interface MediaStats {
  totalFiles: number
  totalSize: number
  filesByType: Record<MediaType, number>
  filesByCategory: Record<string, number>
}

// 媒体文件查询参数
export interface MediaQueryParams {
  type?: MediaType
  category?: string
  tags?: string[]
  search?: string
  sortBy?: 'name' | 'createdAt' | 'modifiedAt' | 'size'
  sortOrder?: 'asc' | 'desc'
  page?: number
  limit?: number
}

// 文件ID到文件名的映射表
const fileIdToFileNameMap: Record<string, string> = {}

// 生成唯一的文件ID
const generateFileId = (fileName: string): string => {
  // 使用文件名生成一个简单的哈希值作为ID
  const hash = fileName.split('').reduce((acc, char) => {
    return acc + char.charCodeAt(0);
  }, 0);
  
  const id = `audio_${hash}`;
  fileIdToFileNameMap[id] = fileName;
  return id;
}

// 根据文件ID获取文件名
export const getFileNameById = (id: string): string | undefined => {
  return fileIdToFileNameMap[id];
}

// 媒体文件查询结果
export interface MediaQueryResult {
  files: MediaFileWithId[]
  total: number
  stats: MediaStats
}

// 处理媒体文件信息
const processMediaFile = (path: string, url: string): MediaFileWithId => {
  // 从路径中提取文件名
  const fileName = path.split('/').pop() || '';
  const fileExtension = fileName.split('.').pop()?.toLowerCase() || '';
  
  // 确定媒体类型
  let type: MediaType = 'other';
  if (['jpg', 'jpeg', 'png', 'gif', 'webp', 'heic', 'bmp'].includes(fileExtension)) {
    type = 'image';
  } else if (['mp4', 'webm', 'ogg', 'mov', 'avi', 'wmv', 'flv'].includes(fileExtension)) {
    type = 'video';
  } else if (['mp3', 'wav', 'aac', 'flac', 'm4a'].includes(fileExtension)) {
    type = 'audio';
  }
  
  // 使用文件ID而不是基于时间的ID
  const id = generateFileId(fileName);
  
  // 确定类别
  let category = 'other';
  if (type === 'image') {
    if (fileName.toLowerCase().includes('landscape') || fileName.toLowerCase().includes('风景')) {
      category = 'landscape';
    } else if (fileName.toLowerCase().includes('portrait') || fileName.toLowerCase().includes('人像')) {
      category = 'portrait';
    } else if (fileName.toLowerCase().includes('food') || fileName.toLowerCase().includes('美食')) {
      category = 'food';
    } else {
      category = 'photo';
    }
  } else if (type === 'video') {
    if (fileName.toLowerCase().includes('movie') || fileName.toLowerCase().includes('电影')) {
      category = 'movie';
    } else if (fileName.toLowerCase().includes('music') || fileName.toLowerCase().includes('音乐')) {
      category = 'music';
    } else {
      category = 'video';
    }
  } else if (type === 'audio') {
    if (fileName.toLowerCase().includes('music') || fileName.toLowerCase().includes('音乐')) {
      category = 'music';
    } else if (fileName.toLowerCase().includes('podcast') || fileName.toLowerCase().includes('播客')) {
      category = 'podcast';
    } else {
      category = 'audio';
    }
  }
  
  // 生成标签
  const tags: string[] = [];
  if (type === 'image') {
    tags.push('图片');
    if (category === 'landscape') tags.push('风景');
    if (category === 'portrait') tags.push('人像');
    if (category === 'food') tags.push('美食');
  } else if (type === 'video') {
    tags.push('视频');
    if (category === 'movie') tags.push('电影');
    if (category === 'music') tags.push('音乐视频');
  } else if (type === 'audio') {
    tags.push('音频');
    if (category === 'music') tags.push('音乐');
    if (category === 'podcast') tags.push('播客');
  }
  
  // 创建文件路径（从public/media开始的相对路径）
  const filePath = path.replace('../../../public/', '/').replace('/public/', '/').replace('/media/', '/media/');
  
  // 处理Vite返回的URL
  let processedUrl = url;
  
  // 移除/public/前缀，Vite会自动处理这个路径
  if (processedUrl.startsWith('/public/')) {
    processedUrl = processedUrl.replace('/public/', '/');
  }
  
  // 移除?url查询参数
  if (processedUrl.endsWith('?url')) {
    processedUrl = processedUrl.slice(0, -4);
  }
  
  // 对于音频文件，使用原始文件名而不进行编码
  if (type === 'audio') {
    // 确保URL以/media/开头
    if (!processedUrl.includes('/media/')) {
      processedUrl = `/media/audios/${fileName}`;
    }
  } else {
    // 对于其他文件类型，使用编码后的文件名
    if (processedUrl.includes('/media/')) {
      // 提取文件名部分
      const urlParts = processedUrl.split('/');
      const originalFileName = urlParts[urlParts.length - 1];
      
      // 检查文件名是否已经编码（如果包含%则可能已经编码）
      const isAlreadyEncoded = originalFileName && originalFileName.includes('%');
      
      // 只有在未编码且包含特殊字符时才进行编码
      if (!isAlreadyEncoded && originalFileName && (originalFileName.includes(' ') || originalFileName.includes('(') || originalFileName.includes(')') || originalFileName.includes('-') || /[\u4e00-\u9fa5]/.test(originalFileName))) {
        // 对文件名进行编码
        let encodedFileName = encodeURIComponent(originalFileName);
        
        // 替换URL中的文件名部分
        urlParts[urlParts.length - 1] = encodedFileName;
        processedUrl = urlParts.join('/');
        
        console.log(`文件名包含特殊字符，已进行编码: ${originalFileName} -> ${encodedFileName}`);
      }
    }
  }
  
  // 确保URL以/media/开头，而不是/public/media/
  if (!processedUrl.includes('/media/')) {
    // 根据文件类型构建正确的URL
    if (type === 'image') {
      // 对文件名进行编码，确保特殊字符正确处理
      let encodedFileName = encodeURIComponent(fileName);
      processedUrl = `/media/images/${encodedFileName}`;
    } else if (type === 'video') {
      // 对文件名进行编码，确保特殊字符正确处理
      let encodedFileName = encodeURIComponent(fileName);
      processedUrl = `/media/videos/${encodedFileName}`;
    } else {
      // 对于其他类型，使用原始路径但确保正确格式
      let encodedFileName = encodeURIComponent(fileName);
      processedUrl = `/media/other/${encodedFileName}`;
    }
  }
  
  console.log(`处理媒体文件: ${fileName}, 原始URL: ${url}, 处理后URL: ${processedUrl}`);
  
  return {
    id,
    name: fileName,
    path: filePath,
    url: processedUrl,
    type,
    size: 0, // 无法从URL获取文件大小
    format: fileExtension,
    category,
    tags,
    createdAt: new Date(Date.now() - Math.floor(Math.random() * 30 * 24 * 60 * 60 * 1000)).toISOString(),
    modifiedAt: new Date().toISOString(),
    lastModified: new Date(Date.now() - Math.floor(Math.random() * 30 * 24 * 60 * 60 * 1000)).toISOString()
  };
};

// 获取所有本地媒体文件
const getAllLocalMediaFiles = async (): Promise<MediaFileWithId[]> => {
  try {
    console.log('Starting to load local media files...');
    
    // 首先尝试使用import.meta.glob加载媒体文件
    let files: MediaFileWithId[] = [];
    
    try {
      // 使用Vite的特殊查询语法来获取公共资源的URL
      // 尝试多种模式以确保能加载到媒体文件
      let mediaModules: Record<string, () => Promise<string>> = {}
      
      try {
        // 直接从public目录加载，但使用正确的路径格式
        mediaModules = import.meta.glob('/media/**/*', { query: '?url', import: 'default' }) as Record<string, () => Promise<string>>
        console.log('从 /media/ 加载媒体文件')
      } catch (error) {
        console.warn('从 /media/ 加载失败，尝试从 /public/media/ 加载:', error)
        // 如果失败，尝试从绝对路径加载
        mediaModules = import.meta.glob('/public/media/**/*', { query: '?url', import: 'default' }) as Record<string, () => Promise<string>>
      }
      
      console.log('Found media modules:', Object.keys(mediaModules));
      console.log('Total media modules count:', Object.keys(mediaModules).length);
      
      // 特别检查音频文件
      const audioModules = Object.keys(mediaModules).filter(key => key.includes('/audios/'));
      console.log('Found audio modules:', audioModules);
      console.log('Total audio modules count:', audioModules.length);
      
      // 如果没有找到任何媒体文件，直接使用静态文件列表
      if (Object.keys(mediaModules).length === 0) {
        console.log('没有找到任何媒体文件模块，使用静态文件列表');
        files = getStaticMediaFiles();
      } else {
        for (const path in mediaModules) {
          try {
            console.log(`Loading media file from path: ${path}`);
            // 获取文件的URL
            let url = await mediaModules[path]();
            
            // 处理URL - 确保使用正确的路径格式
            // 移除/public/前缀，Vite会自动处理这个路径
            if (url.startsWith('/public/')) {
              url = url.replace('/public/', '/');
            }
            
            // 移除?url查询参数
            if (url.endsWith('?url')) {
              url = url.slice(0, -4);
            }
            
            // 处理媒体文件
            const mediaFile = processMediaFile(path, url);
            files.push(mediaFile);
            console.log(`Successfully loaded media file: ${mediaFile.name}, type: ${mediaFile.type}`);
          } catch (error) {
            console.error(`加载媒体文件 ${path} 时出错:`, error);
            
            // 使用错误处理工具处理单个文件加载错误
            await ErrorHandlerUtils.handleError(
              ErrorHandlerUtils.createNetworkError(
                `加载媒体文件 ${path} 时出错`,
                { path, error, operation: 'loadSingleMediaFile' }
              )
            );
          }
        }
      }
    } catch (globError) {
      console.warn('使用import.meta.glob加载媒体文件失败，回退到静态文件列表:', globError);
      
      // 使用错误处理工具处理错误
      await ErrorHandlerUtils.handleError(
        ErrorHandlerUtils.createNetworkError(
          '使用import.meta.glob加载媒体文件失败',
          { globError, operation: 'importMetaGlob' }
        )
      );
      
      // 如果import.meta.glob失败，使用静态文件列表作为后备方案
      files = getStaticMediaFiles();
    }
    
    // 如果仍然没有文件，确保使用静态文件列表
    if (files.length === 0) {
      console.log('没有通过import.meta.glob加载到文件，使用静态文件列表');
      
      // 使用错误处理工具处理空数据情况
      await ErrorHandlerUtils.handleError(
        ErrorHandlerUtils.createDataEmptyError(
          '通过import.meta.glob没有加载到媒体文件',
          { operation: 'importMetaGlob' }
        )
      );
      
      files = getStaticMediaFiles();
    }
    
    // 验证文件列表不为空
    ErrorHandlerUtils.validateDataNotEmpty(
      files,
      '媒体文件列表为空',
      { operation: 'getAllLocalMediaFiles' }
    );
    
    console.log(`成功加载 ${files.length} 个媒体文件`);
    console.log('Files by type:', {
      image: files.filter(f => f.type === 'image').length,
      video: files.filter(f => f.type === 'video').length,
      audio: files.filter(f => f.type === 'audio').length,
      other: files.filter(f => f.type === 'other').length
    });
    
    // 打印前几个音频文件的详细信息
    const audioFiles = files.filter(f => f.type === 'audio');
    if (audioFiles.length > 0) {
      console.log('前3个音频文件的详细信息:');
      audioFiles.slice(0, 3).forEach((file, index) => {
        console.log(`音频文件 ${index + 1}:`, {
          id: file.id,
          name: file.name,
          url: file.url,
          type: file.type,
          format: file.format
        });
      });
    }
    
    return files.sort((file1, file2) => ((file1.name || '') > (file2.name || '') ? 1 : -1));
  } catch (error) {
    console.error('加载媒体文件时出错:', error);
    
    // 使用错误处理工具处理错误
    await ErrorHandlerUtils.handleError(
      error instanceof Error ? error : new Error(String(error)),
      { operation: 'getAllLocalMediaFiles' }
    );
    
    // 返回静态文件列表作为最后的后备方案
    return getStaticMediaFiles();
  }
};

