// 获取媒体文件统计信息
const getMediaStats = (files: MediaFileWithId[]): MediaStats => {
  const stats: MediaStats = {
    totalFiles: files.length,
    totalSize: files.reduce((sum, file) => sum + file.size, 0),
    filesByType: {
      image: 0,
      video: 0,
      audio: 0,
      other: 0
    },
    filesByCategory: {}
  };
  
  // 按类型统计
  files.forEach(file => {
    stats.filesByType[file.type]++;
    
    // 按类别统计
    if (!stats.filesByCategory[file.category]) {
      stats.filesByCategory[file.category] = 0;
    }
    stats.filesByCategory[file.category]++;
  });
  
  return stats;
};

// 查询媒体文件
const queryMediaFiles = async (params: MediaQueryParams = {}): Promise<MediaQueryResult> => {
  const allFiles = await getAllLocalMediaFiles();
  
  // 过滤文件
  let filteredFiles = allFiles.filter(file => {
    // 按类型过滤
    if (params.type && file.type !== params.type) {
      return false;
    }
    
    // 按类别过滤
    if (params.category && file.category !== params.category) {
      return false;
    }
    
    // 按标签过滤
    if (params.tags && params.tags.length > 0) {
      const hasAllTags = params.tags.every(tag => file.tags.includes(tag));
      if (!hasAllTags) {
        return false;
      }
    }
    
    // 按搜索词过滤
    if (params.search) {
      const searchLower = params.search.toLowerCase();
      const nameMatch = file.name && file.name.toLowerCase().includes(searchLower);
      const tagMatch = file.tags.some(tag => tag.toLowerCase().includes(searchLower));
      if (!nameMatch && !tagMatch) {
        return false;
      }
    }
    
    return true;
  });
  
  // 排序
  const sortBy = params.sortBy || 'name';
  const sortOrder = params.sortOrder || 'asc';
  
  filteredFiles.sort((a, b) => {
    let aValue: any = a[sortBy as keyof MediaFileWithId];
    let bValue: any = b[sortBy as keyof MediaFileWithId];
    
    // 处理字符串比较
    if (typeof aValue === 'string') {
      aValue = aValue.toLowerCase();
      bValue = (bValue as string).toLowerCase();
    }
    
    if (sortOrder === 'asc') {
      return aValue > bValue ? 1 : aValue < bValue ? -1 : 0;
    } else {
      return aValue < bValue ? 1 : aValue > bValue ? -1 : 0;
    }
  });
  
  // 分页
  const page = params.page || 1;
  const limit = params.limit || filteredFiles.length;
  const startIndex = (page - 1) * limit;
  const endIndex = startIndex + limit;
  const paginatedFiles = filteredFiles.slice(startIndex, endIndex);
  
  return {
    files: paginatedFiles,
    total: filteredFiles.length,
    stats: getMediaStats(allFiles)
  };
};

// 按类型获取媒体文件
const getMediaFilesByType = async (type: MediaType): Promise<MediaFileWithId[]> => {
  const result = await queryMediaFiles({ type });
  return result.files;
};

// 按类别获取媒体文件
const getMediaFilesByCategory = async (category: string): Promise<MediaFileWithId[]> => {
  const result = await queryMediaFiles({ category });
  return result.files;
};

// 搜索媒体文件
const searchMediaFiles = async (searchTerm: string, type?: MediaType): Promise<MediaFileWithId[]> => {
  const params: MediaQueryParams = { search: searchTerm };
  if (type) {
    params.type = type;
  }
  const result = await queryMediaFiles(params);
  return result.files;
};

// 获取单个媒体文件
const getMediaFileById = async (id: string): Promise<MediaFileWithId | null> => {
  const allFiles = await getAllLocalMediaFiles();
  return allFiles.find(file => file.id === id) || null;
};

// 获取所有媒体文件类别
const getMediaCategories = async (): Promise<string[]> => {
  const allFiles = await getAllLocalMediaFiles();
  const categories = new Set<string>();
  allFiles.forEach(file => {
    if (file.category) {
      categories.add(file.category);
    }
  });
  return Array.from(categories);
};

// 获取所有媒体文件标签
const getMediaTags = async (): Promise<string[]> => {
  const allFiles = await getAllLocalMediaFiles();
  const tags = new Set<string>();
  allFiles.forEach(file => {
    file.tags.forEach(tag => {
      tags.add(tag);
    });
  });
  return Array.from(tags);
};

// 统一媒体API
export const unifiedMediaApi = {
  // 查询方法
  queryMediaFiles,
  getMediaFilesByType,
  getMediaFilesByCategory,
  searchMediaFiles,
  getMediaFileById,
  
  // 统计方法
  getMediaStats: () => getMediaStats(getAllLocalMediaFiles()),
  
  // 类别和标签方法
  getMediaCategories,
  getMediaTags,
  
  // 刷新方法
  refreshMediaFiles: getAllLocalMediaFiles
};

// 导出类型
export type {
  MediaFileWithId,
  MediaStats,
  MediaQueryParams,
  MediaQueryResult
};

// React Hook for using media files
export const useMediaFiles = (params?: MediaQueryParams) => {
  const [files, setFiles] = useState<MediaFileWithId[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const loadFiles = async () => {
      try {
        setLoading(true);
        setError(null);
        const result = await queryMediaFiles(params || {});
        setFiles(result.files);
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : '未知错误';
        setError(errorMessage);
        console.error('加载媒体文件失败:', err);
      } finally {
        setLoading(false);
      }
    };

    loadFiles();
  }, [JSON.stringify(params)]);

  return { files, loading, error };
};