import React from 'react';
import { Link } from 'react-router-dom';
import { Card, CardContent, CardActions, Typography, Chip, Avatar, Box, Button } from '@mui/material';
import { CalendarToday, Visibility, ThumbUp, Comment } from '@mui/icons-material';
import { BlogPostListItem } from '../../types/blog';
import LazyImage from './LazyImage';

interface ArticleCardProps {
  post: BlogPostListItem;
  featured?: boolean;
}

const ArticleCard: React.FC<ArticleCardProps> = ({ post, featured = false }) => {
  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleDateString('zh-CN', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  };

  return (
    <Card 
      sx={{ 
        height: '100%', 
        display: 'flex', 
        flexDirection: 'column',
        transition: 'transform 0.2s ease-in-out, box-shadow 0.2s ease-in-out',
        '&:hover': {
          transform: 'translateY(-4px)',
          boxShadow: 4
        }
      }}
    >
      {post.coverImage && (
        <Box sx={{ height: featured ? 240 : 160, overflow: 'hidden' }}>
          <Link to={`/blog/${post.slug}`} style={{ textDecoration: 'none' }}>
            <LazyImage 
              src={post.coverImage} 
              alt={post.title} 
              style={{ 
                width: '100%', 
                height: '100%', 
                objectFit: 'cover' 
              }}
            />
          </Link>
        </Box>
      )}
      
      <CardContent sx={{ flexGrow: 1, pb: 1 }}>
        <Typography 
          variant={featured ? "h4" : "h5"} 
          component={Link}
          to={`/blog/${post.slug}`}
          gutterBottom
          sx={{ 
            fontWeight: 'bold',
            lineHeight: 1.2,
            color: 'text.primary',
            textDecoration: 'none',
            '&:hover': {
              textDecoration: 'underline',
              color: 'primary.main'
            }
          }}
        >
          {post.title}
        </Typography>
        
        <Typography 
          variant="body2" 
          color="text.secondary" 
          paragraph
          sx={{ 
            display: '-webkit-box',
            WebkitLineClamp: featured ? 3 : 2,
            WebkitBoxOrient: 'vertical',
            overflow: 'hidden'
          }}
        >
          {post.excerpt}
        </Typography>
        
        {post.tags && post.tags.length > 0 && (
          <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5, mb: 2 }}>
            {post.tags.slice(0, featured ? 6 : 3).map((tag) => (
              <Chip 
                key={tag} 
                label={tag} 
                size="small" 
                variant="outlined" 
                sx={{ fontSize: '0.75rem' }}
              />
            ))}
            {post.tags.length > (featured ? 6 : 3) && (
              <Chip 
                label={`+${post.tags.length - (featured ? 6 : 3)}`} 
                size="small" 
                variant="outlined" 
                sx={{ fontSize: '0.75rem' }}
              />
            )}
          </Box>
        )}
        
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <Box sx={{ display: 'flex', alignItems: 'center' }}>
            <Avatar 
              sx={{ width: 24, height: 24, mr: 1 }}
              src={post.author.picture}
              alt={post.author.name}
            >
              {post.author.name.charAt(0)}
            </Avatar>
            <Typography variant="body2" color="text.secondary">
              {post.author.name}
            </Typography>
          </Box>
          
          <Box sx={{ display: 'flex', alignItems: 'center', color: 'text.secondary' }}>
            <CalendarToday sx={{ fontSize: 16, mr: 0.5 }} />
            <Typography variant="body2">
              {post.date ? formatDate(post.date) : (post.createdAt ? formatDate(post.createdAt) : '')}
            </Typography>
          </Box>
        </Box>
      </CardContent>
      
      <CardActions sx={{ justifyContent: 'space-between', px: 2, pb: 2 }}>
        <Box sx={{ display: 'flex', gap: 2 }}>
          {post.viewCount !== undefined && (
            <Box sx={{ display: 'flex', alignItems: 'center' }}>
              <Visibility sx={{ fontSize: 16, mr: 0.5 }} />
              <Typography variant="body2">{post.viewCount}</Typography>
            </Box>
          )}
          
          {post.likeCount !== undefined && (
            <Box sx={{ display: 'flex', alignItems: 'center' }}>
              <ThumbUp sx={{ fontSize: 16, mr: 0.5 }} />
              <Typography variant="body2">{post.likeCount}</Typography>
            </Box>
          )}
          
          {post.commentCount !== undefined && (
            <Box sx={{ display: 'flex', alignItems: 'center' }}>
              <Comment sx={{ fontSize: 16, mr: 0.5 }} />
              <Typography variant="body2">{post.commentCount}</Typography>
            </Box>
          )}
        </Box>
        
        <Button 
          component={Link}
          to={`/blog/${post.slug}`}
          size="small" 
          sx={{ fontWeight: 'bold' }}
        >
          阅读更多
        </Button>
      </CardActions>
    </Card>
  );
};

export default ArticleCard;