import { RouterProvider } from 'react-router-dom'
import { Provider } from 'react-redux'
import { store } from './store'
import ThemeProvider from './components/common/ThemeProvider'
import LoadingIndicator from './components/common/LoadingIndicator'
import GlobalMusicPlayer from './components/Entertainment/GlobalMusicPlayer'
import router from './router'
import { useEffect, useState } from 'react'
import globalMusicService from './services/globalMusicService'
import entertainmentPreloadService from './services/entertainmentPreloadService'
import pageAutoPlayService from './services/pageAutoPlayService'

function App() {
  const [isInitializing, setIsInitializing] = useState(true)
  const [isLoadingMedia, setIsLoadingMedia] = useState(false)
  
  // 初始化全局音乐服务和预加载娱乐模块数据
  useEffect(() => {
    const initializeApp = async () => {
      try {
        // 初始化全局音乐服务
        await globalMusicService.initialize()
        console.log('全局音乐服务初始化成功')
        
        // 异步预加载娱乐模块数据，不阻塞应用启动
        const preloadEntertainmentData = async () => {
          try {
            if (!entertainmentPreloadService.hasPreloaded()) {
              setIsLoadingMedia(true)
              console.log('开始异步预加载娱乐模块数据...')
              await entertainmentPreloadService.preloadAllEntertainmentData()
              console.log('娱乐模块数据预加载成功')
            }
          } catch (error) {
            console.error('娱乐模块数据预加载失败:', error)
            // 预加载失败不影响应用正常使用
          } finally {
            setIsLoadingMedia(false)
          }
        }
        
        // 使用setTimeout确保预加载不会阻塞应用渲染
        setTimeout(preloadEntertainmentData, 100)
        
        // 初始化页面自动播放服务
        await pageAutoPlayService.initialize()
        console.log('页面自动播放服务初始化成功')
      } catch (error) {
        console.error('应用初始化失败:', error)
      } finally {
        // 应用初始化完成，隐藏初始化加载状态
        setIsInitializing(false)
      }
    }
    
    initializeApp()
  }, [])

  return (
    <Provider store={store}>
      <ThemeProvider>
        <RouterProvider router={router} />
        <GlobalMusicPlayer />
        <LoadingIndicator 
          open={isInitializing} 
          message="应用初始化中..." 
        />
        <LoadingIndicator 
          open={isLoadingMedia} 
          message="加载媒体数据中..." 
        />
      </ThemeProvider>
    </Provider>
  )
}

export default App