import { createApi, fetchBaseQuery } from '@reduxjs/toolkit/query/react'
import type { RootState } from '../index'

export interface Tutorial {
  _id: string
  title: string
  slug: string
  description: string
  content: string
  coverImage?: string
  difficulty: 'beginner' | 'intermediate' | 'advanced'
  duration: number // in minutes
  tags: string[]
  category: string
  published: boolean
  featured: boolean
  views: number
  likes: number
  comments: string[]
  author: {
    id: string
    username: string
    avatar?: string
  }
  resources: {
    title: string
    url: string
    type: 'download' | 'link' | 'code'
  }[]
  createdAt: string
  updatedAt: string
}

export interface TutorialsResponse {
  success: boolean
  data: Tutorial[]
  pagination: {
    page: number
    limit: number
    total: number
    totalPages: number
  }
}

export interface TutorialResponse {
  success: boolean
  data: Tutorial
}

export interface CreateTutorialRequest {
  title: string
  description: string
  content: string
  coverImage?: string
  difficulty: 'beginner' | 'intermediate' | 'advanced'
  duration: number
  tags: string[]
  category: string
  published?: boolean
  featured?: boolean
  resources?: {
    title: string
    url: string
    type: 'download' | 'link' | 'code'
  }[]
}

export const tutorialApi = createApi({
  reducerPath: 'tutorialApi',
  baseQuery: fetchBaseQuery({
    baseUrl: '/api/v1/tutorials',
    prepareHeaders: (headers, { getState }) => {
      const token = (getState() as RootState).auth.token
      if (token) {
        headers.set('authorization', `Bearer ${token}`)
      }
      return headers
    },
  }),
  tagTypes: ['Tutorial'],
  endpoints: (builder) => ({
    getTutorials: builder.query<TutorialsResponse, { page?: number; limit?: number; difficulty?: string; category?: string; tag?: string }>({
      query: ({ page = 1, limit = 10, difficulty, category, tag }) => {
        let queryParams = `?page=${page}&limit=${limit}`
        if (difficulty) queryParams += `&difficulty=${difficulty}`
        if (category) queryParams += `&category=${category}`
        if (tag) queryParams += `&tag=${tag}`
        return queryParams
      },
      providesTags: ['Tutorial'],
    }),
    getTutorial: builder.query<TutorialResponse, string>({
      query: (id) => `/${id}`,
      providesTags: (_result, _error, id) => [{ type: 'Tutorial', id }],
    }),
    createTutorial: builder.mutation<TutorialResponse, CreateTutorialRequest>({
      query: (tutorial) => ({
        url: '',
        method: 'POST',
        body: tutorial,
      }),
      invalidatesTags: ['Tutorial'],
    }),
    updateTutorial: builder.mutation<TutorialResponse, { id: string; data: Partial<CreateTutorialRequest> }>({
      query: ({ id, data }) => ({
        url: `/${id}`,
        method: 'PUT',
        body: data,
      }),
      invalidatesTags: (_result, _error, { id }) => [{ type: 'Tutorial', id }],
    }),
    deleteTutorial: builder.mutation<void, string>({
      query: (id) => ({
        url: `/${id}`,
        method: 'DELETE',
      }),
      invalidatesTags: ['Tutorial'],
    }),
    likeTutorial: builder.mutation<TutorialResponse, string>({
      query: (id) => ({
        url: `/${id}/like`,
        method: 'POST',
      }),
      invalidatesTags: (_result, _error, id) => [{ type: 'Tutorial', id }],
    }),
    getFeaturedTutorials: builder.query<TutorialsResponse, void>({
      query: () => '/featured',
      providesTags: ['Tutorial'],
    }),
  }),
})

export const {
  useGetTutorialsQuery,
  useGetTutorialQuery,
  useCreateTutorialMutation,
  useUpdateTutorialMutation,
  useDeleteTutorialMutation,
  useLikeTutorialMutation,
  useGetFeaturedTutorialsQuery,
} = tutorialApi