import { v4 as uuidv4 } from 'uuid'
import { getMediaTypeFromExtension, isFileSizeValid, formatFileSize } from '../config/mediaConfig'
import { getFileList, createMediaFile, getFileUrl } from '../api/fileScanner'
import { validateMediaPath, getMediaFileUrl as getValidatedMediaFileUrl, isEntertainmentPath } from '../utils/pathValidator'
import { getMediaUrl } from '../config/mediaCdn'

export interface MediaFile {
  id: string
  name: string
  path: string
  url: string
  type: 'image' | 'video' | 'audio'
  size: number
  format: string
  category?: string
  thumbnail?: string
  duration?: number
  lastModified?: string
  metadata?: {
    width?: number
    height?: number
    artist?: string
    album?: string
    title?: string
    year?: number
    genre?: string
  }
  tags: string[]
  createdAt: string
  modifiedAt: string
}

export interface DirectoryScanResult {
  files: MediaFile[]
  totalCount: number
  success: boolean
  error?: string
}

class MediaFileService {
  private static instance: MediaFileService

  private constructor() {}

  static getInstance(): MediaFileService {
    if (!MediaFileService.instance) {
      MediaFileService.instance = new MediaFileService()
    }
    return MediaFileService.instance
  }

  /**
   * 扫描指定目录中的媒体文件
   * @param directoryPath 要扫描的目录路径
   * @param fileTypes 要扫描的文件类型
   * @returns Promise<DirectoryScanResult> 扫描结果
   */
  async scanDirectory(
    directoryPath: string,
    fileTypes: string[] = ['jpg', 'jpeg', 'png', 'gif', 'mp4', 'avi', 'mov', 'mp3', 'wav', 'flac']
  ): Promise<DirectoryScanResult> {
    try {
      // 在浏览器环境中，我们无法直接访问文件系统
      // 因此我们需要模拟扫描过程，但在实际应用中，这应该是一个API调用
      
      // 模拟扫描延迟
      await new Promise(resolve => setTimeout(resolve, 500))
      
      // 验证路径
      const pathValidation = validateMediaPath(directoryPath)
      if (!pathValidation.isValid) {
        console.error('路径验证失败:', pathValidation.errorMessage)
        return {
          success: false,
          files: [],
          totalCount: 0,
          error: pathValidation.errorMessage
        }
      }
      
      // 使用文件扫描API获取实际文件列表
      const fileNames = await getFileList(directoryPath)
      
      // 根据目录路径确定要扫描的媒体类型
      let mediaType: 'image' | 'video' | 'audio' | null = null
      
      // 优先检查娱乐模块路径
      if (directoryPath.includes('/entertainment/images') || directoryPath.includes('entertainment/photo')) {
        mediaType = 'image'
      } else if (directoryPath.includes('/entertainment/videos') || directoryPath.includes('entertainment/media')) {
        mediaType = 'video'
      } else if (directoryPath.includes('/entertainment/audios') || directoryPath.includes('entertainment/music')) {
        mediaType = 'audio'
      }
      // 检查通用路径
      else if (directoryPath.includes('/images') || directoryPath.endsWith('images')) {
        mediaType = 'image'
      } else if (directoryPath.includes('/videos') || directoryPath.endsWith('videos')) {
        mediaType = 'video'
      } else if (directoryPath.includes('/audios') || directoryPath.endsWith('audios')) {
        mediaType = 'audio'
      }
      
      // 如果没有指定特定类型，扫描所有类型
      const typesToScan = mediaType ? [mediaType] : ['image', 'video', 'audio']
      
      // 直接在这里处理文件，避免调用getActualMediaFiles方法
      const mediaFiles: MediaFile[] = []
      
      for (const type of typesToScan) {
        try {
          // 尝试获取目录中的文件列表
          // 根据路径确定正确的目录URL
          let dirUrl = `/media/${type}s/`
          
          // 如果是娱乐模块路径，确保使用正确的URL
          if (directoryPath.includes('/entertainment')) {
            dirUrl = `/media/${type}s/` // 娱乐模块也使用相同的媒体目录
          }
          
          // 使用获取到的实际文件名列表
          const possibleFileNames: string[] = fileNames.filter(name => {
            const extension = name.split('.').pop()?.toLowerCase()
            if (!extension) return false
            
            if (type === 'image') {
              return ['jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp'].includes(extension)
            } else if (type === 'video') {
              return ['mp4', 'avi', 'mov', 'wmv', 'flv', 'webm'].includes(extension)
            } else if (type === 'audio') {
              return ['mp3', 'wav', 'flac', 'aac', 'ogg'].includes(extension)
            }
            
            return false
          })
          
          // 为每个可能的文件创建MediaFile对象
          for (const fileName of possibleFileNames) {
            try {
                // 构建文件URL - 使用相对路径
                const fileUrl = getMediaUrl(`${type}s/${encodeURIComponent(fileName)}`)
              
              // 检查文件是否存在
              const exists = await this.checkFileExists(fileUrl)
              
              if (exists) {
                // 创建MediaFile对象
                const mediaFile = this.createMediaFileFromUrl(fileName, directoryPath, fileUrl, type)
                mediaFiles.push(mediaFile)
              }
            } catch (error) {
              // 忽略错误，继续尝试下一个文件
            }
          }
        } catch (error) {
          console.warn(`扫描${type}文件时出错:`, error)
        }
      }
      
      return {
        success: true,
        files: mediaFiles,
        totalCount: mediaFiles.length
      }
    } catch (error) {
      console.error('扫描目录失败:', error)
      return {
        success: false,
        files: [],
        totalCount: 0,
        error: error instanceof Error ? error.message : 'Unknown error occurred'
      }
    }
  }

  /**
   * 从URL创建MediaFile对象
   * @param fileName 文件名
   * @param directoryPath 目录路径
   * @param fileUrl 文件URL
   * @param type 媒体类型
   * @returns MediaFile 媒体文件对象
   */
  private createMediaFileFromUrl(
    fileName: string,
    directoryPath: string,
    fileUrl: string,
    type: 'image' | 'video' | 'audio'
  ): MediaFile {
    const now = new Date()
    const nowString = now.toISOString()
    const extension = fileName.split('.').pop()?.toLowerCase() || ''
    
    // 确保使用正确的URL
    const correctUrl = getMediaUrl(`${type}s/${encodeURIComponent(fileName)}`)
    
    return {
      id: uuidv4(),
      name: fileName,
      path: directoryPath,
      url: correctUrl,
      type,
      size: 0, // 在实际应用中，应该通过HEAD请求获取文件大小
      format: extension,
      thumbnail: type === 'video' ? `${correctUrl}?thumbnail=true` : undefined,
      tags: [],
      createdAt: nowString,
      modifiedAt: nowString
    }
  }

  /**
   * 检查文件是否存在
   * @param url 文件URL
   * @returns Promise<boolean> 文件是否存在
   */
  private async checkFileExists(url: string): Promise<boolean> {
    try {
      const response = await fetch(url, { method: 'HEAD' })
      return response.ok
    } catch (error) {
      return false
    }
  }

  /**
   * 获取媒体文件详细信息
   * @param file 媒体文件
   * @returns Promise<MediaFile> 更新后的媒体文件
   */
  async getMediaFileDetails(file: MediaFile): Promise<MediaFile> {
    try {
      // 在实际应用中，这里应该通过API获取文件的详细信息
      // 包括文件大小、元数据等
      
      // 模拟获取文件详细信息
      const updatedFile = { ...file }
      
      // 模拟获取文件大小
      try {
        const response = await fetch(file.url, { method: 'HEAD' })
        if (response.ok) {
          const contentLength = response.headers.get('content-length')
          if (contentLength) {
            updatedFile.size = parseInt(contentLength, 10)
          }
        }
      } catch (error) {
        console.warn('获取文件大小失败:', error)
      }
      
      // 根据文件类型获取特定信息
      if (file.type === 'image') {
        // 获取图片尺寸等信息
        try {
          const img = new Image()
          img.src = file.url
          
          await new Promise((resolve, reject) => {
            img.onload = resolve
            img.onerror = reject
          })
          
          updatedFile.metadata = {
            ...updatedFile.metadata,
            width: img.width,
            height: img.height
          }
        } catch (error) {
          console.warn('获取图片尺寸失败:', error)
        }
      } else if (file.type === 'audio') {
        // 获取音频时长等信息
        try {
          const audio = new Audio()
          audio.src = file.url
          
          await new Promise((resolve, reject) => {
            audio.addEventListener('loadedmetadata', resolve)
            audio.addEventListener('error', reject)
          })
          
          updatedFile.duration = audio.duration
          updatedFile.metadata = {
            ...updatedFile.metadata,
            title: audio.title || file.name,
            artist: audio.artist || '',
            album: audio.album || ''
          }
        } catch (error) {
          console.warn('获取音频信息失败:', error)
        }
      } else if (file.type === 'video') {
        // 获取视频时长和尺寸等信息
        try {
          const video = document.createElement('video')
          video.src = file.url
          
          await new Promise((resolve, reject) => {
            video.addEventListener('loadedmetadata', resolve)
            video.addEventListener('error', reject)
          })
          
          updatedFile.duration = video.duration
          updatedFile.metadata = {
            ...updatedFile.metadata,
            width: video.videoWidth,
            height: video.videoHeight,
            title: video.title || file.name
          }
        } catch (error) {
          console.warn('获取视频信息失败:', error)
        }
      }
      
      return updatedFile
    } catch (error) {
      console.error('获取媒体文件详细信息失败:', error)
      return file
    }
  }

  /**
   * 按类型过滤媒体文件
   * @param files 媒体文件数组
   * @param type 媒体类型
   * @returns MediaFile[] 过滤后的媒体文件数组
   */
  filterByType(files: MediaFile[], type: 'image' | 'video' | 'audio'): MediaFile[] {
    return files.filter(file => file.type === type)
  }

  /**
   * 按标签过滤媒体文件
   * @param files 媒体文件数组
   * @param tags 标签数组
   * @returns MediaFile[] 过滤后的媒体文件数组
   */
  filterByTags(files: MediaFile[], tags: string[]): MediaFile[] {
    return files.filter(file => 
      tags.some(tag => file.tags.includes(tag))
    )
  }

  /**
   * 按名称搜索媒体文件
   * @param files 媒体文件数组
   * @param query 搜索查询
   * @returns MediaFile[] 搜索结果
   */
  searchByName(files: MediaFile[], query: string): MediaFile[] {
    const lowerQuery = query.toLowerCase()
    return files.filter(file => 
      file.name.toLowerCase().includes(lowerQuery)
    )
  }

  /**
   * 按修改日期排序媒体文件
   * @param files 媒体文件数组
   * @param ascending 是否升序
   * @returns MediaFile[] 排序后的媒体文件数组
   */
  sortByDate(files: MediaFile[], ascending = false): MediaFile[] {
    return [...files].sort((a, b) => {
      const dateA = a.modifiedAt.getTime()
      const dateB = b.modifiedAt.getTime()
      return ascending ? dateA - dateB : dateB - dateA
    })
  }

  /**
   * 按名称排序媒体文件
   * @param files 媒体文件数组
   * @param ascending 是否升序
   * @returns MediaFile[] 排序后的媒体文件数组
   */
  sortByName(files: MediaFile[], ascending = true): MediaFile[] {
    return [...files].sort((a, b) => {
      const nameA = a.name.toLowerCase()
      const nameB = b.name.toLowerCase()
      if (ascending) {
        return nameA.localeCompare(nameB)
      } else {
        return nameB.localeCompare(nameA)
      }
    })
  }

  /**
   * 按大小排序媒体文件
   * @param files 媒体文件数组
   * @param ascending 是否升序
   * @returns MediaFile[] 排序后的媒体文件数组
   */
  sortBySize(files: MediaFile[], ascending = false): MediaFile[] {
    return [...files].sort((a, b) => {
      return ascending ? a.size - b.size : b.size - a.size
    })
  }

  /**
   * 为媒体文件添加标签
   * @param file 媒体文件
   * @param tags 要添加的标签
   * @returns MediaFile 更新后的媒体文件
   */
  addTags(file: MediaFile, tags: string[]): MediaFile {
    const newTags = tags.filter(tag => !file.tags.includes(tag))
    return {
      ...file,
      tags: [...file.tags, ...newTags],
      modifiedAt: new Date().toISOString()
    }
  }

  /**
   * 从媒体文件中移除标签
   * @param file 媒体文件
   * @param tags 要移除的标签
   * @returns MediaFile 更新后的媒体文件
   */
  removeTags(file: MediaFile, tags: string[]): MediaFile {
    return {
      ...file,
      tags: file.tags.filter(tag => !tags.includes(tag)),
      modifiedAt: new Date().toISOString()
    }
  }

  /**
   * 从媒体文件列表中获取所有分类
   * @param files 媒体文件数组
   * @returns string[] 分类数组
   */
  getCategories(files: MediaFile[]): string[] {
    const categories = new Set<string>()
    files.forEach(file => {
      if (file.category) {
        categories.add(file.category)
      }
    })
    return Array.from(categories).sort()
  }

  /**
   * 从媒体文件列表中获取所有标签
   * @param files 媒体文件数组
   * @returns string[] 标签数组
   */
  getTags(files: MediaFile[]): string[] {
    const tags = new Set<string>()
    files.forEach(file => {
      file.tags.forEach(tag => {
        tags.add(tag)
      })
    })
    return Array.from(tags).sort()
  }

  /**
   * 按分类过滤媒体文件
   * @param files 媒体文件数组
   * @param category 分类
   * @returns MediaFile[] 过滤后的媒体文件数组
   */
  filterByCategory(files: MediaFile[], category: string): MediaFile[] {
    return files.filter(file => file.category === category)
  }

  /**
   * 上传文件
   * @param files 文件列表
   * @param directory 目录类型
   * @returns Promise<MediaFile[]> 上传的媒体文件数组
   */
  async uploadFiles(files: FileList, directory: 'images' | 'videos' | 'audios'): Promise<MediaFile[]> {
    const mediaFiles: MediaFile[] = []
    
    for (let i = 0; i < files.length; i++) {
      const file = files[i]
      const mediaType = directory.slice(0, -1) as 'image' | 'video' | 'audio'
      
      // 使用正确的URL
      const correctUrl = getMediaUrl(`${directory}/${encodeURIComponent(file.name)}`)
      
      const mediaFile = this.createMediaFileFromUrl(
        file.name,
        `/media/${directory}/`,
        correctUrl,
        mediaType
      )
      mediaFiles.push(mediaFile)
    }
    
    return mediaFiles
  }
}

export default MediaFileService.getInstance()