import { createApi, fetchBaseQuery } from '@reduxjs/toolkit/query/react'
import type { RootState } from '../index'

export interface Experience {
  _id: string
  title: string
  company: string
  location: string
  period: {
    start: string
    end?: string
    current: boolean
  }
  description: string
  responsibilities: string[]
  achievements: string[]
  technologies: string[]
  type: 'work' | 'education' | 'project'
  featured: boolean
  order: number
  createdAt: string
  updatedAt: string
}

export interface ExperiencesResponse {
  success: boolean
  data: Experience[]
}

export interface ExperienceResponse {
  success: boolean
  data: Experience
}

export interface CreateExperienceRequest {
  title: string
  company: string
  location: string
  period: {
    start: string
    end?: string
    current: boolean
  }
  description: string
  responsibilities: string[]
  achievements: string[]
  technologies: string[]
  type: 'work' | 'education' | 'project'
  featured?: boolean
  order?: number
}

export const experienceApi = createApi({
  reducerPath: 'experienceApi',
  baseQuery: fetchBaseQuery({
    baseUrl: '/api/v1/experiences',
    prepareHeaders: (headers, { getState }) => {
      const token = (getState() as RootState).auth.token
      if (token) {
        headers.set('authorization', `Bearer ${token}`)
      }
      return headers
    },
  }),
  tagTypes: ['Experience'],
  endpoints: (builder) => ({
    getExperiences: builder.query<ExperiencesResponse, { type?: string; featured?: boolean }>({
      query: ({ type, featured }) => {
        let queryParams = ''
        if (type) queryParams += `?type=${type}`
        if (featured !== undefined) queryParams += type ? `&featured=${featured}` : `?featured=${featured}`
        return queryParams
      },
      providesTags: ['Experience'],
    }),
    getExperience: builder.query<ExperienceResponse, string>({
      query: (id) => `/${id}`,
      providesTags: (_result, _error, id) => [{ type: 'Experience', id }],
    }),
    createExperience: builder.mutation<ExperienceResponse, CreateExperienceRequest>({
      query: (experience) => ({
        url: '',
        method: 'POST',
        body: experience,
      }),
      invalidatesTags: ['Experience'],
    }),
    updateExperience: builder.mutation<ExperienceResponse, { id: string; data: Partial<CreateExperienceRequest> }>({
      query: ({ id, data }) => ({
        url: `/${id}`,
        method: 'PUT',
        body: data,
      }),
      invalidatesTags: (_result, _error, { id }) => [{ type: 'Experience', id }],
    }),
    deleteExperience: builder.mutation<void, string>({
      query: (id) => ({
        url: `/${id}`,
        method: 'DELETE',
      }),
      invalidatesTags: ['Experience'],
    }),
    reorderExperiences: builder.mutation<void, { experiences: { id: string; order: number }[] }>({
      query: (experiences) => ({
        url: '/reorder',
        method: 'POST',
        body: experiences,
      }),
      invalidatesTags: ['Experience'],
    }),
  }),
})

export const {
  useGetExperiencesQuery,
  useGetExperienceQuery,
  useCreateExperienceMutation,
  useUpdateExperienceMutation,
  useDeleteExperienceMutation,
  useReorderExperiencesMutation,
} = experienceApi