import React from 'react'
import { useSelector } from 'react-redux'
import { Navigate } from 'react-router-dom'
import { RootState } from '../../store'
import { hasPermission, hasAnyPermission, Permission } from '../../utils/permissions.tsx'

interface ProtectedRouteProps {
  children: React.ReactNode
  requiredPermission?: Permission
  requiredPermissions?: Permission[]
  fallbackPath?: string
  fallbackComponent?: React.ReactNode
}

/**
 * 权限路由保护组件
 * 根据用户权限决定是否渲染子组件或重定向到指定路径
 */
export const ProtectedRoute: React.FC<ProtectedRouteProps> = ({
  children,
  requiredPermission,
  requiredPermissions,
  fallbackPath = '/login',
  fallbackComponent,
}) => {
  const { user, isAuthenticated } = useSelector((state: RootState) => state.auth)
  
  // 如果用户未登录，重定向到登录页
  if (!isAuthenticated) {
    return <Navigate to={fallbackPath} replace />
  }
  
  // 检查权限
  let hasRequiredPermission = true
  
  if (requiredPermission) {
    hasRequiredPermission = hasPermission(user, requiredPermission)
  } else if (requiredPermissions) {
    hasRequiredPermission = hasAnyPermission(user, requiredPermissions)
  }
  
  // 如果没有权限，显示fallback组件或重定向
  if (!hasRequiredPermission) {
    return fallbackComponent ? <>{fallbackComponent}</> : <Navigate to="/unauthorized" replace />
  }
  
  return <>{children}</>
}

interface ConditionalRenderProps {
  children: React.ReactNode
  requiredPermission?: Permission
  requiredPermissions?: Permission[]
  fallback?: React.ReactNode
}

/**
 * 条件渲染组件
 * 根据用户权限决定是否渲染子组件
 */
export const ConditionalRender: React.FC<ConditionalRenderProps> = ({
  children,
  requiredPermission,
  requiredPermissions,
  fallback = null,
}) => {
  const { user } = useSelector((state: RootState) => state.auth)
  
  // 检查权限
  let hasRequiredPermission = true
  
  if (requiredPermission) {
    hasRequiredPermission = hasPermission(user, requiredPermission)
  } else if (requiredPermissions) {
    hasRequiredPermission = hasAnyPermission(user, requiredPermissions)
  }
  
  return hasRequiredPermission ? <>{children}</> : <>{fallback}</>
}

/**
 * 权限检查Hook
 * 返回一个函数，用于检查当前用户是否有特定权限
 */
export const usePermissionCheck = () => {
  const { user } = useSelector((state: RootState) => state.auth)
  
  const checkPermission = (permission: Permission): boolean => {
    return hasPermission(user, permission)
  }
  
  const checkAnyPermission = (permissions: Permission[]): boolean => {
    return hasAnyPermission(user, permissions)
  }
  
  const checkAllPermissions = (permissions: Permission[]): boolean => {
    return permissions.every(p => hasPermission(user, p))
  }
  
  const canEditResource = (resourceAuthorId: string): boolean => {
    if (hasPermission(user, Permission.EDIT_ANY_BLOG) || 
        hasPermission(user, Permission.EDIT_ANY_COMMENT) || 
        hasPermission(user, Permission.EDIT_ANY_PROFILE)) {
      return true
    }
    
    return user?.id === resourceAuthorId && 
           (hasPermission(user, Permission.EDIT_OWN_BLOG) || 
            hasPermission(user, Permission.EDIT_OWN_COMMENT) || 
            hasPermission(user, Permission.EDIT_OWN_PROFILE))
  }
  
  const canDeleteResource = (resourceAuthorId: string): boolean => {
    if (hasPermission(user, Permission.DELETE_ANY_BLOG) || 
        hasPermission(user, Permission.DELETE_ANY_COMMENT)) {
      return true
    }
    
    return user?.id === resourceAuthorId && 
           (hasPermission(user, Permission.DELETE_OWN_BLOG) || 
            hasPermission(user, Permission.DELETE_OWN_COMMENT))
  }
  
  return {
    checkPermission,
    checkAnyPermission,
    checkAllPermissions,
    canEditResource,
    canDeleteResource,
  }
}