import { MediaFile } from '../services/mediaFileService'

class MediaNavigationService {
  private static instance: MediaNavigationService
  private navigationHistory: Array<{ moduleId: string, fileId?: string, timestamp: number }> = []
  private currentMediaFile: MediaFile | null = null

  private constructor() {}

  static getInstance(): MediaNavigationService {
    if (!MediaNavigationService.instance) {
      MediaNavigationService.instance = new MediaNavigationService()
    }
    return MediaNavigationService.instance
  }

  // 记录导航历史
  recordNavigation(moduleId: string, fileId?: string): void {
    this.navigationHistory.push({
      moduleId,
      fileId,
      timestamp: Date.now()
    })

    // 限制历史记录数量
    if (this.navigationHistory.length > 10) {
      this.navigationHistory = this.navigationHistory.slice(-10)
    }
  }

  // 获取导航历史
  getNavigationHistory(): Array<{ moduleId: string, fileId?: string, timestamp: number }> {
    return [...this.navigationHistory]
  }

  // 设置当前媒体文件
  setCurrentMediaFile(file: MediaFile): void {
    this.currentMediaFile = file
  }

  // 获取当前媒体文件
  getCurrentMediaFile(): MediaFile | null {
    return this.currentMediaFile
  }

  // 根据文件类型获取模块路径
  getModulePathByFileType(fileType: string): string {
    switch (fileType) {
      case 'image':
        return '/entertainment/PhotoWall'
      case 'video':
        return '/entertainment/MediaLibrary'
      case 'audio':
        return '/entertainment/Music'
      default:
        return '/entertainment'
    }
  }

  // 根据模块路径获取文件类型
  getFileTypeByModulePath(path: string): string {
    if (path.includes('/PhotoWall')) return 'image'
    if (path.includes('/MediaLibrary')) return 'video'
    if (path.includes('/Music')) return 'audio'
    return 'unknown'
  }

  // 创建带文件ID的导航URL
  createNavigationUrl(file: MediaFile): string {
    const basePath = this.getModulePathByFileType(file.type)
    return `${basePath}?fileId=${file.id}`
  }

  // 从URL中提取文件ID
  extractFileIdFromUrl(url: string): string | null {
    const urlObj = new URL(url, window.location.origin)
    return urlObj.searchParams.get('fileId')
  }

  // 清除当前媒体文件
  clearCurrentMediaFile(): void {
    this.currentMediaFile = null
  }
}

export default MediaNavigationService