import { MediaFile, MediaFileService } from './mediaFileService'
import ConfigService from './configService'
import { getMediaTypeFromExtension } from '../config/mediaConfig'
import { validateMediaPath, getMediaFileUrl, isEntertainmentPath } from '../utils/pathValidator'
import { unifiedMediaApi } from '../store/api/unifiedMediaApi'

/**
 * 媒体扫描服务
 * 负责扫描指定目录中的媒体文件，并返回媒体文件列表
 */
export class MediaScannerService {
  private static instance: MediaScannerService
  private scanInterval: number | null = null
  private lastScanResults: Map<string, MediaFile[]> = new Map()
  private callbacks: Array<(files: MediaFile[]) => void> = []

  private constructor() {}

  static getInstance(): MediaScannerService {
    if (!MediaScannerService.instance) {
      MediaScannerService.instance = new MediaScannerService()
    }
    return MediaScannerService.instance
  }

  /**
   * 开始定期扫描
   * @param interval 扫描间隔（毫秒）
   */
  startPeriodicScan(interval: number = 60000): void {
    // 如果已经在扫描，先停止
    this.stopPeriodicScan()
    
    // 立即执行一次扫描
    this.performScan()
    
    // 设置定期扫描
    this.scanInterval = window.setInterval(() => {
      this.performScan()
    }, interval)
  }

  /**
   * 停止定期扫描
   */
  stopPeriodicScan(): void {
    if (this.scanInterval) {
      window.clearInterval(this.scanInterval)
      this.scanInterval = null
    }
  }

  /**
   * 添加文件变化回调
   * @param callback 回调函数
   */
  addFileChangeCallback(callback: (files: MediaFile[]) => void): void {
    this.callbacks.push(callback)
  }

  /**
   * 移除文件变化回调
   * @param callback 回调函数
   */
  removeFileChangeCallback(callback: (files: MediaFile[]) => void): void {
    const index = this.callbacks.indexOf(callback)
    if (index !== -1) {
      this.callbacks.splice(index, 1)
    }
  }

  /**
   * 执行扫描
   */
  private async performScan(): Promise<void> {
    try {
      const files = await this.scanAllMediaDirectories()
      
      // 检查是否有变化
      const currentFilesKey = JSON.stringify(files.map(f => ({ id: f.id, modifiedAt: f.modifiedAt })))
      const lastFilesKey = JSON.stringify(
        Array.from(this.lastScanResults.values())
          .flat()
          .map(f => ({ id: f.id, modifiedAt: f.modifiedAt }))
      )
      
      if (currentFilesKey !== lastFilesKey) {
        // 文件有变化，通知所有回调
        this.callbacks.forEach(callback => callback(files))
        
        // 更新上次扫描结果
        this.lastScanResults.set('all', files)
      }
    } catch (error) {
      console.error('定期扫描失败:', error)
    }
  }

  /**
   * 扫描指定类型的媒体文件目录
   * @param type 媒体类型 ('image' | 'video' | 'audio')
   * @returns Promise<MediaFile[]> 媒体文件数组
   */
  async scanMediaDirectory(type: 'image' | 'video' | 'audio'): Promise<MediaFile[]> {
    try {
      // 使用ConfigService获取媒体目录路径
      const directoryPath = ConfigService.getMediaDirectoryPath(`${type}s` as 'images' | 'videos' | 'audios')
      
      // 获取实际媒体文件
      const files = await this.getActualMediaFiles(type, directoryPath)
      return files
    } catch (error) {
      console.error(`扫描${type}文件失败:`, error)
      throw new Error(`扫描${type}文件失败: ${error instanceof Error ? error.message : '未知错误'}`)
    }
  }

  /**
   * 扫描所有媒体目录
   * @returns Promise<MediaFile[]>
   */
  async scanAllMediaDirectories(): Promise<MediaFile[]> {
    const mediaTypes: ('image' | 'video' | 'audio')[] = ['image', 'video', 'audio']
    const results = await Promise.allSettled(
      mediaTypes.map(type => this.scanMediaDirectory(type))
    )
    
    const mediaFiles: MediaFile[] = []
    
    results.forEach((result, index) => {
      if (result.status === 'fulfilled') {
        mediaFiles.push(...result.value)
      } else {
        console.error(`扫描媒体目录失败 (${mediaTypes[index]}):`, result.reason)
      }
    })
    
    return mediaFiles
  }

  /**
   * 从文件列表创建媒体文件对象
   * @param files 文件列表
   * @param directoryPath 目录路径
   * @returns Promise<MediaFile[]> 媒体文件数组
   */
  async createMediaFilesFromFileList(files: FileList, directoryPath?: string): Promise<MediaFile[]> {
    const mediaFiles: MediaFile[] = []
    
    for (let i = 0; i < files.length; i++) {
      const file = files[i]
      const mediaFile = await this.createMediaFileFromFile(file, directoryPath)
      mediaFiles.push(mediaFile)
    }
    
    return mediaFiles
  }

  /**
   * 从单个文件创建媒体文件对象
   * @param file 文件对象
   * @param directoryPath 目录路径
   * @returns Promise<MediaFile> 媒体文件对象
   */
  private async createMediaFileFromFile(file: File, directoryPath?: string): Promise<MediaFile> {
    const fileType = getMediaTypeFromExtension(file.name)
    
    if (!fileType) {
      throw new Error(`不支持的文件类型: ${file.name}`)
    }
    
    const id = this.generateId()
    const fileName = file.name
    const fileTypeForConfig = `${fileType}s` as 'images' | 'videos' | 'audios'
    const path = directoryPath ? `${directoryPath}/${fileName}` : `${ConfigService.getMediaDirectoryPath(fileTypeForConfig)}/${fileName}`
    const url = URL.createObjectURL(file)
    
    const mediaFile: MediaFile = {
      id,
      name: fileName,
      path,
      url,
      type: fileType,
      size: file.size,
      format: fileName.split('.').pop() || '',
      tags: [],
      createdAt: new Date(),
      modifiedAt: new Date(),
      lastModified: new Date(file.lastModified)
    }
    
    // 如果是图片，尝试获取尺寸信息
    if (fileType === 'image') {
      mediaFile.metadata = await this.getImageMetadata(file)
    }
    
    return mediaFile
  }

  /**
   * 获取图片元数据
   * @param file 图片文件
   * @returns Promise<Object> 图片元数据
   */
  private async getImageMetadata(file: File): Promise<{ width?: number; height?: number }> {
    return new Promise((resolve) => {
      const img = new Image()
      img.onload = () => {
        resolve({
          width: img.width,
          height: img.height
        })
      }
      img.onerror = () => {
        resolve({})
      }
      img.src = URL.createObjectURL(file)
    })
  }

  /**
   * 生成唯一ID
   * @returns string 唯一ID
   */
  private generateId(): string {
    return Date.now().toString(36) + Math.random().toString(36).substr(2)
  }

  /**
   * 获取实际的媒体文件
   * @param type 媒体类型
   * @param directoryPath 目录路径
   * @returns Promise<MediaFile[]> 媒体文件数组
   */
  private async getActualMediaFiles(type: 'image' | 'video' | 'audio', directoryPath: string): Promise<MediaFile[]> {
    // 验证路径
    const pathValidation = validateMediaPath(directoryPath)
    if (!pathValidation.isValid) {
      console.error('路径验证失败:', pathValidation.errorMessage)
      return []
    }
    
    // 使用统一媒体API获取媒体文件
    let mediaFiles: MediaFile[] = []
    
    try {
      // 根据类型获取媒体文件
      const filesByType = await unifiedMediaApi.getMediaFilesByType(type)
      
      // 过滤出在指定目录下的文件
      mediaFiles = filesByType.filter(file => file.path.startsWith(directoryPath))
      
      console.log(`使用统一媒体API从 ${directoryPath} 获取到 ${mediaFiles.length} 个${type}文件`)
    } catch (apiError) {
      console.warn(`统一媒体API获取文件失败，尝试备用方法:`, apiError)
      
      // 备用方法：尝试直接从URL获取文件列表
      try {
        // 构建媒体目录URL - 确保不包含/public/前缀
        let mediaDirUrl = `/media/${type}s/`
        
        // 如果是娱乐模块路径，确保使用正确的URL
        if (isEntertainmentPath(directoryPath)) {
          mediaDirUrl = `/media/${type}s/` // 娱乐模块也使用相同的媒体目录
        }
        
        const response = await fetch(mediaDirUrl)
        if (response.ok) {
          const data = await response.json()
          if (data.files && Array.isArray(data.files)) {
            // 根据类型过滤文件
            const possibleFileNames = data.files.filter((fileName: string) => {
              const extension = fileName.split('.').pop()?.toLowerCase()
              if (!extension) return false
              
              if (type === 'image') {
                return ['jpg', 'jpeg', 'png', 'gif', 'webp', 'heic', 'bmp'].includes(extension.toLowerCase())
              } else if (type === 'video') {
                return ['mp4', 'webm', 'ogg', 'mov', 'avi', 'wmv', 'flv'].includes(extension.toLowerCase())
              } else if (type === 'audio') {
                return ['mp3', 'wav', 'ogg', 'aac', 'flac', 'm4a'].includes(extension.toLowerCase())
              }
              
              return false
            })
            
            // 为每个可能的文件创建MediaFile对象
            for (const fileName of possibleFileNames) {
              try {
                // 构建文件URL - 确保正确编码
                const fileUrl = `${mediaDirUrl}${encodeURIComponent(fileName)}`
                
                // 检查文件是否存在
                const exists = await this.checkFileExists(fileUrl)
                
                if (exists) {
                  const id = this.generateId()
                  const fileExtension = fileName.split('.').pop() || ''
                  
                  // 创建文件路径
                  const path = `${directoryPath}/${fileName}`
                  
                  const mediaFile: MediaFile = {
                    id,
                    name: fileName,
                    path,
                    url: fileUrl,
                    type,
                    size: 0, // 无法从URL获取文件大小
                    format: fileExtension,
                    category: this.getRandomCategory(type),
                    tags: this.getRandomTags(type),
                    createdAt: new Date(Date.now() - Math.floor(Math.random() * 30 * 24 * 60 * 60 * 1000)),
                    modifiedAt: new Date(),
                    lastModified: new Date(Date.now() - Math.floor(Math.random() * 30 * 24 * 60 * 60 * 1000))
                  }
                  
                  // 添加特定类型的元数据
                  if (type === 'image') {
                    // 对于图片，尝试获取尺寸信息
                    if (fileExtension === 'heic') {
                      // HEIC文件需要特殊处理，这里使用默认值
                      mediaFile.metadata = {
                        width: 3024,
                        height: 4032
                      }
                    } else {
                      // 对于其他图片格式，可以尝试加载获取尺寸
                      try {
                        const dimensions = await this.getImageDimensions(fileUrl)
                        mediaFile.metadata = {
                          width: dimensions.width,
                          height: dimensions.height
                        }
                      } catch (error) {
                        // 如果无法获取尺寸，使用默认值
                        mediaFile.metadata = {
                          width: 1920,
                          height: 1080
                        }
                      }
                    }
                  } else if (type === 'video') {
                    mediaFile.duration = 120 // 2分钟
                    mediaFile.metadata = {
                      width: 1920,
                      height: 1080
                    }
                  } else if (type === 'audio') {
                    mediaFile.duration = 180 // 3分钟
                    mediaFile.metadata = {
                      artist: '测试艺术家',
                      album: '测试专辑',
                      title: fileName.replace(/\.[^/.]+$/, ""), // 移除文件扩展名
                      year: 2023,
                      genre: '测试'
                    }
                  }
                  
                  mediaFiles.push(mediaFile)
                }
              } catch (fileError) {
                console.warn(`处理文件 ${fileName} 时出错:`, fileError)
              }
            }
          }
        }
      } catch (fallbackError) {
        console.warn(`备用方法也失败，使用默认文件列表:`, fallbackError)
        
        // 最后的备用方法：使用默认文件列表
        const defaultFiles = this.getDefaultFiles(type)
        for (const fileName of defaultFiles) {
          try {
            const fileUrl = `/media/${type}s/${encodeURIComponent(fileName)}`
            const exists = await this.checkFileExists(fileUrl)
            
            if (exists) {
              const id = this.generateId()
              const fileExtension = fileName.split('.').pop() || ''
              
              const mediaFile: MediaFile = {
                id,
                name: fileName,
                path: `${directoryPath}/${fileName}`,
                url: fileUrl,
                type,
                size: 0,
                format: fileExtension,
                category: this.getRandomCategory(type),
                tags: this.getRandomTags(type),
                createdAt: new Date(Date.now() - Math.floor(Math.random() * 30 * 24 * 60 * 60 * 1000)),
                modifiedAt: new Date(),
                lastModified: new Date(Date.now() - Math.floor(Math.random() * 30 * 24 * 60 * 60 * 1000))
              }
              
              mediaFiles.push(mediaFile)
            }
          } catch (fileError) {
            console.warn(`处理默认文件 ${fileName} 时出错:`, fileError)
          }
        }
      }
    }
    
    console.log(`从 ${directoryPath} 扫描到 ${mediaFiles.length} 个${type}文件`)
    return mediaFiles
  }
  
  /**
   * 检查文件是否存在
   * @param url 文件URL
   * @returns Promise<boolean> 文件是否存在
   */
  private async checkFileExists(url: string): Promise<boolean> {
    try {
      const response = await fetch(url, { method: 'HEAD' })
      return response.ok
    } catch (error) {
      return false
    }
  }

  /**
   * 获取图片尺寸
   * @param url 图片URL
   * @returns Promise<{width: number, height: number}> 图片尺寸
   */
  private async getImageDimensions(url: string): Promise<{ width: number; height: number }> {
    return new Promise((resolve, reject) => {
      const img = new Image()
      img.onload = () => {
        resolve({
          width: img.width,
          height: img.height
        })
      }
      img.onerror = () => {
        reject(new Error('无法加载图片'))
      }
      img.src = url
    })
  }

  /**
   * 获取随机分类
   * @param type 媒体类型
   * @returns string 随机分类
   */
  private getRandomCategory(type: 'image' | 'video' | 'audio'): string {
    const categories = {
      image: ['风景', '人物', '城市', '旅行', '美食', '其他'],
      video: ['电影', '纪录片', '短视频', '家庭', '活动', '其他'],
      audio: ['流行', '摇滚', '古典', '爵士', '电子', '其他']
    }
    
    const categoryList = categories[type]
    return categoryList[Math.floor(Math.random() * categoryList.length)]
  }

  /**
   * 获取随机标签
   * @param type 媒体类型
   * @returns string[] 随机标签数组
   */
  private getRandomTags(type: 'image' | 'video' | 'audio'): string[] {
    const allTags = {
      image: ['风景', '自然', '人物', '肖像', '城市', '建筑', '旅行', '记录', '美食', '生活'],
      video: ['旅行', '记录', '家庭', '聚会', '活动', '演讲', '电影', '娱乐', '教育', '纪录片'],
      audio: ['轻松', '背景音乐', '运动', '激励', '专注', '工作', '流行', '经典', '新歌', '收藏']
    }
    
    const tagList = allTags[type]
    const count = Math.floor(Math.random() * 3) + 1 // 1-3个标签
    const tags: string[] = []
    
    for (let i = 0; i < count; i++) {
      const randomIndex = Math.floor(Math.random() * tagList.length)
      const tag = tagList[randomIndex]
      
      if (!tags.includes(tag)) {
        tags.push(tag)
      }
    }
    
    return tags
  }
}

// 导出单例实例
export default MediaScannerService.getInstance()