/**
 * 路径验证工具
 * 用于验证和规范化媒体文件路径
 */

/**
 * 路径验证结果
 */
export interface PathValidationResult {
  isValid: boolean
  normalizedPath?: string
  mediaType?: 'image' | 'video' | 'audio'
  errorMessage?: string
}

/**
 * 验证媒体文件路径
 * @param path 要验证的路径
 * @returns PathValidationResult 验证结果
 */
export function validateMediaPath(path: string): PathValidationResult {
  if (!path || typeof path !== 'string') {
    return {
      isValid: false,
      errorMessage: '路径不能为空且必须是字符串'
    }
  }

  // 规范化路径，确保使用正斜杠
  const normalizedPath = path.replace(/\\/g, '/')
  
  // 检查路径是否包含非法字符
  const invalidChars = /[<>:"|?*]/
  if (invalidChars.test(normalizedPath)) {
    return {
      isValid: false,
      errorMessage: '路径包含非法字符'
    }
  }

  // 确定媒体类型
  let mediaType: 'image' | 'video' | 'audio' | null = null
  
  // 优先检查娱乐模块路径
  if (normalizedPath.includes('/entertainment/images') || normalizedPath.includes('entertainment/photo')) {
    mediaType = 'image'
  } else if (normalizedPath.includes('/entertainment/videos') || normalizedPath.includes('entertainment/media')) {
    mediaType = 'video'
  } else if (normalizedPath.includes('/entertainment/audios') || normalizedPath.includes('entertainment/music')) {
    mediaType = 'audio'
  }
  // 检查通用路径
  else if (normalizedPath.includes('/images') || normalizedPath.endsWith('images')) {
    mediaType = 'image'
  } else if (normalizedPath.includes('/videos') || normalizedPath.endsWith('videos')) {
    mediaType = 'video'
  } else if (normalizedPath.includes('/audios') || normalizedPath.endsWith('audios')) {
    mediaType = 'audio'
  }

  if (!mediaType) {
    return {
      isValid: false,
      errorMessage: '无法从路径确定媒体类型'
    }
  }

  return {
    isValid: true,
    normalizedPath,
    mediaType
  }
}

/**
 * 获取媒体文件的正确URL路径
 * @param directoryPath 目录路径
 * @param fileName 文件名
 * @returns string 文件URL
 */
export function getMediaFileUrl(directoryPath: string, fileName: string): string {
  const validation = validateMediaPath(directoryPath)
  
  if (!validation.isValid) {
    console.error('路径验证失败:', validation.errorMessage)
    return ''
  }
  
  if (!validation.mediaType) {
    console.error('无法确定媒体类型')
    return ''
  }
  
  // 检查是否在GitHub Pages环境中
  const isGitHubPages = typeof window !== 'undefined' && window.location.hostname.includes('github.io')
  
  if (isGitHubPages) {
    // GitHub Pages环境，使用GitHub Releases URL
    return `https://github.com/${getGitHubOwner()}/${getGitHubRepo()}/releases/download/media-assets/${validation.mediaType}s/${encodeURIComponent(fileName)}`
  }
  
  // 构建媒体URL
  return `/media/${validation.mediaType}s/${fileName}`
}

/**
 * 获取GitHub仓库所有者
 * @returns string 仓库所有者
 */
function getGitHubOwner(): string {
  // 从环境变量或配置中获取GitHub仓库所有者
  // 这里使用默认值，实际项目中应该从配置中读取
  return 'u-madara'
}

/**
 * 获取GitHub仓库名称
 * @returns string 仓库名称
 */
function getGitHubRepo(): string {
  // 从环境变量或配置中获取GitHub仓库名称
  // 这里使用默认值，实际项目中应该从配置中读取
  return 'u-madara.github.io'
}

/**
 * 检查路径是否为娱乐模块路径
 * @param path 要检查的路径
 * @returns boolean 是否为娱乐模块路径
 */
export function isEntertainmentPath(path: string): boolean {
  const normalizedPath = path.replace(/\\/g, '/')
  return normalizedPath.includes('/entertainment')
}

/**
 * 获取标准化的媒体目录路径
 * @param path 原始路径
 * @returns string 标准化后的路径
 */
export function normalizeMediaDirectoryPath(path: string): string {
  const validation = validateMediaPath(path)
  
  if (!validation.isValid) {
    throw new Error(`路径验证失败: ${validation.errorMessage}`)
  }
  
  if (!validation.mediaType) {
    throw new Error('无法确定媒体类型')
  }
  
  // 如果是娱乐模块路径，返回娱乐模块标准路径
  if (isEntertainmentPath(path)) {
    return `/entertainment/${validation.mediaType}s`
  }
  
  // 返回标准路径
  return `/media/${validation.mediaType}s`
}