const Music: React.FC = () => {
  const navigate = useNavigate()
  const dispatch = useDispatch<AppDispatch>()
  const { category } = useParams<{ category?: string }>()
  const [searchParams] = useSearchParams()
  const fileIdFromUrl = searchParams.get('fileId')
  
  // 检查并使用预加载的数据
  useEffect(() => {
    // 如果没有预加载数据，则触发预加载
    if (!entertainmentPreloadService.hasPreloaded()) {
      entertainmentPreloadService.preloadAllEntertainmentData()
        .then(() => {
          console.log('音乐页面数据预加载完成')
        })
        .catch(error => {
          console.error('音乐页面数据预加载失败:', error)
        })
    }
  }, [dispatch])
  
  // Redux状态
  const filteredFiles = useSelector(selectFilteredMediaFiles)
  const categories = useSelector(selectMediaFilesCategories)
  const tags = useSelector(selectMediaFilesTags)
  const loading = useSelector(selectMediaFilesLoading)
  const error = useSelector(selectMediaFilesError)
  
  // 调试信息
  console.log('Music页面 - 过滤后的文件:', filteredFiles)
  console.log('Music页面 - 音频文件:', filteredFiles.filter(file => file.type === 'audio'))
  console.log('Music页面 - 加载状态:', loading)
  console.log('Music页面 - 错误信息:', error)
  
  // 打印前几个音频文件的详细信息
  const audioFilesList = filteredFiles.filter(file => file.type === 'audio');
  if (audioFilesList.length > 0) {
    console.log('前3个音频文件的详细信息:');
    audioFilesList.slice(0, 3).forEach((file, index) => {
      console.log(`音频文件 ${index + 1}:`, {
        id: file.id,
        name: file.name,
        url: file.url,
        type: file.type,
        format: file.format
      });
    });
  } else {
    console.log('没有找到音频文件');
  }
  
  // 本地状态
  const [searchTerm, setSearchTerm] = useState('')
  const [selectedCategory, setSelectedCategory] = useState('all')
  const [selectedTag, setSelectedTag] = useState('all')
  // 全局音乐播放状态
  const [globalPlaybackState, setGlobalPlaybackState] = useState(globalMusicService.getState())
  const [audioFileInfo, setAudioFileInfo] = useState<Record<string, { size: number; duration: number }>>({})
  const [playlistDialogOpen, setPlaylistDialogOpen] = useState(false)
  const [notificationOpen, setNotificationOpen] = useState(false)
  const [musicPlayerDialogOpen, setMusicPlayerDialogOpen] = useState(false)
  const initialized = useRef(false)
  const [isDragging, setIsDragging] = useState(false)
  const [isVolumeDragging, setIsVolumeDragging] = useState(false)
  const [hoveredTrackId, setHoveredTrackId] = useState<string | null>(null)
  const audioRef = useRef<HTMLAudioElement>(null)

  // 监听全局音乐播放状态变化
  useEffect(() => {
    const handleStateChange = (state: typeof globalPlaybackState) => {
      setGlobalPlaybackState(state)
    }

    globalMusicService.addStateChangeListener(handleStateChange)
    
    return () => {
      globalMusicService.removeStateChangeListener(handleStateChange)
    }
  }, [])

  // 过滤出音频类型的文件
  const audioFiles = filteredFiles.filter(file => file.type === 'audio')

  // 获取音频文件信息
  useEffect(() => {
    const fetchAudioFileInfo = async () => {
      const newAudioFileInfo: Record<string, { size: number; duration: number }> = { ...audioFileInfo }
      
      // 只获取没有信息的文件
      const filesToFetch = audioFiles.filter(audio => !audioFileInfo[audio.id])
      
      if (filesToFetch.length === 0) {
        return // 没有需要获取信息的文件
      }
      
      for (const audio of filesToFetch) {
        try {
          const info = await getAudioFileInfo(audio.url)
          newAudioFileInfo[audio.id] = info
          console.log(`获取音频文件信息: ${audio.name}`, info)
        } catch (error) {
          console.error(`获取音频文件信息失败: ${audio.name}`, error)
          newAudioFileInfo[audio.id] = { size: 0, duration: 0 }
        }
      }
      
      setAudioFileInfo(newAudioFileInfo)
    }
    
    if (audioFiles.length > 0) {
      fetchAudioFileInfo()
    }
  }, [audioFiles.map(f => f.id).join(',')]) // 只依赖文件ID，避免不必要的重新执行

  // 初始化过滤器 - 只在组件挂载时执行一次
  useEffect(() => {
    if (!initialized.current) {
      // 扫描音频文件
      dispatch(scanMediaDirectory('audio'))
      
      // 设置过滤器
      dispatch(setTypeFilter('audio'))
      dispatch(setCategoryFilter(category || 'all'))
      dispatch(setTagFilter('all'))
      dispatch(setSearchQuery(''))
      setSelectedCategory(category || 'all')
      initialized.current = true
      
      // 通知页面自动播放服务页面类型变化
      pageAutoPlayService.onPageChanged('music')
    }
  }, [dispatch, category])

  // 应用过滤器 - 当本地状态变化时
  useEffect(() => {
    if (initialized) {
      dispatch(setTypeFilter('audio'))
      dispatch(setCategoryFilter(selectedCategory))
      dispatch(setTagFilter(selectedTag))
      dispatch(setSearchQuery(searchTerm))
    }
  }, [dispatch, selectedCategory, selectedTag, searchTerm, initialized])

  // 处理URL参数变化
  useEffect(() => {
    if (initialized && category && category !== selectedCategory) {
      setSelectedCategory(category)
    }
  }, [category, selectedCategory, initialized])

  // 初始化播放列表
  useEffect(() => {
    if (initialized) {
      const currentPlaylist = globalMusicService.getState().playlist
      
      // 只有当播放列表为空或发生变化时才更新
      if (currentPlaylist.length === 0 || 
          JSON.stringify(currentPlaylist.map(f => f.id)) !== JSON.stringify(audioFiles.map(f => f.id))) {
        globalMusicService.setPlaylist(audioFiles)
      }
    }
  }, [audioFiles.length, initialized]) // 只依赖长度和初始化状态

  // 处理URL参数中的fileId，自动播放指定文件
  useEffect(() => {
    if (initialized && fileIdFromUrl && audioFiles.length > 0) {
      const targetFile = audioFiles.find(file => file.id === fileIdFromUrl)
      if (targetFile && (!globalPlaybackState.currentTrack || globalPlaybackState.currentTrack.id !== fileIdFromUrl)) {
        // 找到目标文件且当前没有播放或播放的不是目标文件
        playTrack(targetFile)
      }
    }
  }, [initialized, fileIdFromUrl, audioFiles.length, globalPlaybackState.currentTrack])

  // 播放指定曲目 - 使用全局音乐服务
  const playTrack = (track: MediaFile) => {
    console.log(`播放音轨: ${track.name}`);
    
    // 获取当前播放列表
    const currentPlaylist = globalMusicService.getState().playlist
    const audioFiles = filteredFiles.filter(file => file.type === 'audio')
    
    // 只有当播放列表发生变化时才更新
    if (JSON.stringify(currentPlaylist.map(f => f.id)) !== JSON.stringify(audioFiles.map(f => f.id))) {
      globalMusicService.setPlaylist(audioFiles)
    }
    
    // 播放指定曲目
    globalMusicService.playTrack(track)
  }

  // 播放/暂停
  const togglePlayPause = () => {
    if (!globalPlaybackState.currentTrack && audioFiles.length > 0) {
      console.log('没有当前音轨，播放第一个音频文件');
      playTrack(audioFiles[0]);
      return;
    }
    
    globalMusicService.togglePlay();
  }

  // 播放下一首
  const playNext = async () => {
    await globalMusicService.playNext();
  }

  // 播放上一首
  const playPrevious = async () => {
    await globalMusicService.playPrevious();
  }

  // 静音/取消静音
  const toggleMute = () => {
    globalMusicService.toggleMute()
  }

  // 处理音量变化
  const handleVolumeChange = (_event: Event, newValue: number | number[]) => {
    const volume = Array.isArray(newValue) ? newValue[0] : newValue;
    globalMusicService.setVolume(volume);
  }

  // 设置播放模式
  const handlePlayModeChange = (mode: 'list' | 'single' | 'shuffle') => {
    globalMusicService.setPlayMode(mode);
  }

  // 音量滑块拖拽开始
  const handleVolumeDragStart = () => {
    setIsVolumeDragging(true)
  }

  // 音量滑块拖拽结束
  const handleVolumeDragEnd = () => {
    setIsVolumeDragging(false)
  }

  // 处理时间更新 - 使用全局状态
  const handleTimeUpdate = () => {
    // 时间更新由全局音乐服务处理，这里不需要额外处理
  }

  // 处理音频加载 - 使用全局状态
  const handleLoadedMetadata = () => {
    // 音频加载由全局音乐服务处理，这里不需要额外处理
  }

  // 处理进度条变化
  const handleSliderChange = (_event: Event, newValue: number | number[]) => {
    const time = Array.isArray(newValue) ? newValue[0] : newValue;
    globalMusicService.setCurrentTime(time);
  }

  // 进度条拖拽开始
  const handleSliderDragStart = () => {
    setIsDragging(true)
  }

  // 进度条拖拽结束
  const handleSliderDragEnd = () => {
    setIsDragging(false)
  }

  // 处理音频结束 - 使用全局音乐服务
  const handleEnded = () => {
    // 音频结束由全局音乐服务自动处理，这里不需要额外处理
  }

  // 处理分类变化
  const handleCategoryChange = (event: any) => {
    const newCategory = event.target.value
    setSelectedCategory(newCategory)
    
    // 更新URL
    if (newCategory === 'all') {
      navigate('/entertainment/Music')
    } else {
      navigate(`/entertainment/Music/${newCategory}`)
    }
  }

  // 处理标签变化
  const handleTagChange = (event: any) => {
    setSelectedTag(event.target.value)
  }

  // 处理搜索
  const handleSearchChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(event.target.value)
  }

  // 打开播放列表对话框
  const openPlaylistDialog = () => {
    setPlaylistDialogOpen(true)
  }

  // 关闭播放列表对话框
  const closePlaylistDialog = () => {
    setPlaylistDialogOpen(false)
  }

  // 打开音乐播放器对话框
  const openMusicPlayerDialog = () => {
    setMusicPlayerDialogOpen(true)
  }

  // 关闭音乐播放器对话框
  const closeMusicPlayerDialog = () => {
    setMusicPlayerDialogOpen(false)
  }

  // 从播放列表中选择曲目
  const selectTrackFromPlaylist = (track: MediaFile) => {
    globalMusicService.playTrack(track)
    closePlaylistDialog()
  }

  // 关闭通知
  const handleCloseNotification = () => {
    setNotificationOpen(false)
    if (error) {
      dispatch(clearError())
    }
  }

  // 格式化文件大小
  const formatFileSize = (bytes: number): string => {
    if (bytes === 0) return '0 Bytes'
    const k = 1024
    const sizes = ['Bytes', 'KB', 'MB', 'GB']
    const i = Math.floor(Math.log(bytes) / Math.log(k))
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i]
  }

  // 格式化时间
  const formatTime = (seconds: number): string => {
    const mins = Math.floor(seconds / 60)
    const secs = Math.floor(seconds % 60)
    return `${mins}:${secs.toString().padStart(2, '0')}`
  }

  // 获取音频文件信息
  const getAudioFileInfo = async (audioUrl: string): Promise<{ size: number; duration: number }> => {
    try {
      console.log('获取音频文件信息，URL:', audioUrl)
      
      // 创建一个临时的audio元素来获取音频信息
      const audio = new Audio()
      
      // 获取文件大小
      let response: Response
      try {
        response = await fetch(audioUrl, { method: 'HEAD' })
      } catch (fetchError) {
        console.error('获取音频文件信息失败，fetch错误:', fetchError)
        return {
          size: 0,
          duration: 0
        }
      }
      
      const contentLength = response.headers.get('content-length')
      const size = contentLength ? parseInt(contentLength, 10) : 0
      
      // 获取音频时长
      return new Promise((resolve) => {
        audio.addEventListener('loadedmetadata', () => {
          console.log('音频元数据加载成功，时长:', audio.duration)
          resolve({
            size,
            duration: audio.duration || 0
          })
        })
        
        audio.addEventListener('error', (e) => {
          console.error('音频加载错误:', e)
          resolve({
            size,
            duration: 0
          })
        })
        
        // 设置超时，避免长时间等待
        setTimeout(() => {
          console.warn('获取音频信息超时')
          resolve({
            size,
            duration: 0
          })
        }, 5000)
        
        audio.src = audioUrl
      })
    } catch (error) {
      console.error('获取音频文件信息失败:', error)
      return {
        size: 0,
        duration: 0
      }
    }
  }

  return (
    <Container maxWidth="lg">
      {/* 隐藏的音频元素 */}
      <audio
        ref={audioRef}
        onTimeUpdate={handleTimeUpdate}
        onLoadedMetadata={handleLoadedMetadata}
        onEnded={handleEnded}
        onError={(e) => {
          console.error('音频元素错误:', e);
        }}
        onLoadStart={() => {
          console.log('开始加载音频');
        }}
        onCanPlay={() => {
          console.log('音频可以播放');
        }}
        preload="metadata"
      />

      {/* 面包屑导航 */}
      <Breadcrumbs items={[
        { label: '首页', path: '/' },
        { label: '休闲娱乐', path: '/entertainment' },
        { label: '音乐', path: '/entertainment/Music' }
      ]} />

      {/* 页面标题 */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 4 }}>
        <Box>
          <Typography variant="h3" component="h1" gutterBottom fontWeight="bold">
            音乐
          </Typography>
          <Typography variant="h6" color="text.secondary">
            分享喜欢的音乐作品，创建个人播放列表和音乐收藏
          </Typography>
        </Box>
        <Button 
          variant="outlined" 
          startIcon={<HomeIcon />}
          onClick={() => {
            console.log('Navigating to /entertainment')
            navigate('/entertainment')
          }}
        >
          返回休闲娱乐
        </Button>
      </Box>

      {/* 音乐播放器 */}
      {globalPlaybackState.currentTrack && (
        <PlayerContainer elevation={3}>
          <PlayerContent>
            <Box sx={{ 
              display: 'flex', 
              alignItems: 'flex-start', 
              mb: 2,
              flexDirection: { xs: 'column', sm: 'row' }
            }}>
              <PlayerAlbumArt>
                <MusicNoteIcon sx={{ 
                  fontSize: { xs: 40, sm: 60 }, 
                  color: 'rgba(255, 255, 255, 0.8)' 
                }} />
              </PlayerAlbumArt>
              <Box sx={{ 
                flexGrow: 1, 
                mt: { xs: 2, sm: 1 },
                ml: { xs: 0, sm: 0 }
              }}>
                <Typography 
                  variant="h5" 
                  component="h2" 
                  noWrap 
                  gutterBottom 
                  fontWeight="bold"
                  sx={{ fontSize: { xs: '1.25rem', sm: '1.5rem' } }}
                >
                  {globalPlaybackState.currentTrack.name}
                </Typography>
                <Typography 
                  variant="body1" 
                  sx={{ 
                    color: 'rgba(255, 255, 255, 0.8)', 
                    mb: 1,
                    fontSize: { xs: '0.875rem', sm: '1rem' }
                  }}
                >
                  {globalPlaybackState.currentTrack.category}
                </Typography>
                <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                  {globalPlaybackState.currentTrack.tags.map((tag) => (
                    <Chip 
                      key={tag} 
                      label={tag} 
                      size="small" 
                      sx={{ 
                        backgroundColor: 'rgba(255, 255, 255, 0.2)', 
                        color: '#ffffff',
                        backdropFilter: 'blur(10px)',
                        border: '1px solid rgba(255, 255, 255, 0.3)',
                        fontSize: { xs: '0.75rem', sm: '0.8125rem' },
                        '&:hover': {
                          backgroundColor: 'rgba(255, 255, 255, 0.3)',
                        }
                      }} 
                    />
                  ))}
                </Box>
              </Box>
              <IconButton 
                onClick={openPlaylistDialog} 
                sx={{ 
                  color: '#ffffff',
                  position: { xs: 'absolute', sm: 'relative' },
                  top: { xs: 8, sm: 'auto' },
                  right: { xs: 8, sm: 'auto' }
                }}
              >
                <QueueMusicIcon />
              </IconButton>
              <IconButton 
                onClick={openMusicPlayerDialog} 
                sx={{ 
                  color: '#ffffff',
                  position: { xs: 'absolute', sm: 'relative' },
                  top: { xs: 8, sm: 'auto' },
                  right: { xs: 48, sm: 'auto' }
                }}
              >
                <MusicNoteIcon />
              </IconButton>
            </Box>
            
            <ProgressContainer>
              <Box sx={{ display: 'flex', alignItems: 'center' }}>
                <TimeText variant="body2">
                  {formatTime(globalPlaybackState.currentTime)}
                </TimeText>
                <CustomSlider
                  value={globalPlaybackState.currentTime}
                  max={globalPlaybackState.duration}
                  onChange={handleSliderChange}
                  onChangeCommitted={handleSliderDragEnd}
                  onMouseDown={handleSliderDragStart}
                  sx={{ mx: 2, flexGrow: 1 }}
                />
                <TimeText variant="body2">
                  {formatTime(globalPlaybackState.duration)}
                </TimeText>
              </Box>
            </ProgressContainer>
            
            <PlayerControls>
              <ControlButton onClick={playPrevious}>
                <SkipPreviousIcon />
              </ControlButton>
              <PlayPauseButton onClick={togglePlayPause}>
                {globalPlaybackState.isPlaying ? <PauseIcon sx={{ fontSize: 32 }} /> : <PlayArrowIcon sx={{ fontSize: 32 }} />}
              </PlayPauseButton>
              <ControlButton onClick={playNext}>
                <SkipNextIcon />
              </ControlButton>
            </PlayerControls>
            
            <VolumeContainer>
              <ControlButton onClick={toggleMute}>
                {globalPlaybackState.isMuted ? <VolumeOffIcon /> : <VolumeUpIcon />}
              </ControlButton>
              <CustomVolumeSlider
                value={globalPlaybackState.volume}
                max={1}
                step={0.1}
                onChange={handleVolumeChange}
                onChangeCommitted={handleVolumeDragEnd}
                onMouseDown={handleVolumeDragStart}
                sx={{ flexGrow: 1, maxWidth: 120 }}
              />
            </VolumeContainer>
          </PlayerContent>
        </PlayerContainer>
      )}

      {/* 过滤器区域 */}
      <FilterSection>
        <Grid container spacing={3} alignItems="center">
          {/* 搜索框 */}
          <Grid size={{ xs: 12, md: 4 }}>
            <TextField
              fullWidth
              placeholder="搜索音乐..."
              value={searchTerm}
              onChange={handleSearchChange}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <SearchIcon />
                  </InputAdornment>
                ),
              }}
            />
          </Grid>

          {/* 分类过滤器 */}
          <Grid size={{ xs: 12, md: 4 }}>
            <FormControl fullWidth>
              <InputLabel id="category-filter-label">分类</InputLabel>
              <Select
                labelId="category-filter-label"
                value={selectedCategory}
                label="分类"
                onChange={handleCategoryChange}
              >
                <MenuItem value="all">所有分类</MenuItem>
                {categories.map((cat) => (
                  <MenuItem key={cat} value={cat}>
                    {cat}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>

          {/* 标签过滤器 */}
          <Grid size={{ xs: 12, md: 4 }}>
            <FormControl fullWidth>
              <InputLabel id="tag-filter-label">标签</InputLabel>
              <Select
                labelId="tag-filter-label"
                value={selectedTag}
                label="标签"
                onChange={handleTagChange}
              >
                <MenuItem value="all">所有标签</MenuItem>
                {tags.map((tag) => (
                  <MenuItem key={tag} value={tag}>
                    {tag}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
        </Grid>
      </FilterSection>

      {/* 音乐网格 */}
      <StateWrapper
        loading={false}
        error={error}
        empty={audioFiles.length === 0 && !error}
        emptyIcon={<MusicNoteIcon />}
        emptyTitle="没有找到音乐"
        emptyDescription="尝试调整过滤器或上传一些音乐文件"
        emptyAction={{
          label: '返回休闲娱乐',
          onClick: () => {
            console.log('Navigating to /entertainment')
            navigate('/entertainment')
          }
        }}
        errorTitle="加载音乐时出错"
        retryAction={{
          label: '重试',
          onClick: () => window.location.reload()
        }}
      >
        <Grid container spacing={3}>
            {audioFiles.map((audio) => (
              <Grid size={{ xs: 12, sm: 6, md: 4, lg: 3 }} key={audio.id}>
              <SongCard 
                onClick={() => playTrack(audio)}
                onMouseEnter={() => setHoveredTrackId(audio.id)}
                onMouseLeave={() => setHoveredTrackId(null)}
                sx={{
                  transform: hoveredTrackId === audio.id ? 'translateY(-8px)' : 'translateY(0)',
                  boxShadow: hoveredTrackId === audio.id ? '0 12px 24px rgba(0, 0, 0, 0.15)' : '0 4px 12px rgba(0, 0, 0, 0.08)',
                }}
              >
                <SongAlbumArt>
                  <MusicNoteIcon sx={{ fontSize: 80, color: 'rgba(255, 255, 255, 0.8)' }} />
                  {globalPlaybackState.currentTrack?.id === audio.id && globalPlaybackState.isPlaying && (
                    <Box sx={{
                      position: 'absolute',
                      bottom: 8,
                      right: 8,
                      backgroundColor: 'rgba(255, 255, 255, 0.9)',
                      borderRadius: '50%',
                      width: 32,
                      height: 32,
                      display: 'flex',
                      justifyContent: 'center',
                      alignItems: 'center',
                    }}>
                      <MusicNoteIcon sx={{ fontSize: 18, color: '#764ba2' }} />
                    </Box>
                  )}
                </SongAlbumArt>
                <SongContent>
                  <SongTitle variant="h6" component="div">
                    {audio.name}
                  </SongTitle>
                  <SongMeta>
                    <Typography variant="body2" color="text.secondary">
                      {audioFileInfo[audio.id]?.size ? formatFileSize(audioFileInfo[audio.id].size) : formatFileSize(audio.size)}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      {audioFileInfo[audio.id]?.duration ? formatTime(audioFileInfo[audio.id].duration) : (audio.duration ? formatTime(audio.duration) : '--:--')}
                    </Typography>
                  </SongMeta>
                  <SongTags>
                    {audio.tags.map((tag) => (
                      <Chip 
                        key={tag} 
                        label={tag} 
                        size="small" 
                        variant="outlined" 
                        sx={{ 
                          backgroundColor: 'rgba(102, 126, 234, 0.1)',
                          borderColor: 'rgba(102, 126, 234, 0.3)',
                          color: 'primary.main',
                          fontWeight: 'bold',
                          '&:hover': {
                            backgroundColor: 'rgba(102, 126, 234, 0.2)',
                          }
                        }} 
                      />
                    ))}
                  </SongTags>
                  <Box sx={{ mt: 2, display: 'flex', justifyContent: 'center' }}>
                    <SongPlayButton 
                      startIcon={<PlayArrowIcon />}
                      onClick={(e) => {
                        e.stopPropagation()
                        playTrack(audio)
                      }}
                      sx={{
                        transform: hoveredTrackId === audio.id ? 'scale(1.05)' : 'scale(1)',
                      }}
                    >
                      播放
                    </SongPlayButton>
                  </Box>
                </SongContent>
              </SongCard>
            </Grid>
          ))}
        </Grid>
      </StateWrapper>

      {/* 播放列表对话框 */}
      <Dialog 
        open={playlistDialogOpen} 
        onClose={closePlaylistDialog} 
        maxWidth="md" 
        fullWidth
        PaperProps={{
          sx: {
            borderRadius: { xs: 2, sm: 3 },
            maxHeight: { xs: '90vh', sm: '80vh' },
            m: { xs: 1, sm: 2 },
          }
        }}
      >
        <DialogTitle 
          sx={{ 
            pb: { xs: 1, sm: 2 }, 
            fontWeight: 'bold',
            fontSize: { xs: '1.25rem', sm: '1.5rem' },
            pr: { xs: 6, sm: 8 },
          }}
        >
          播放列表
          <IconButton 
            onClick={closePlaylistDialog} 
            sx={{ 
              position: 'absolute', 
              right: { xs: 8, sm: 12 }, 
              top: { xs: 8, sm: 12 },
              p: { xs: 1, sm: 1.5 },
            }}
          >
            <CloseIcon sx={{ fontSize: { xs: 20, sm: 24 } }} />
          </IconButton>
        </DialogTitle>
        <DialogContent sx={{ p: 0 }}>
          <PlaylistContainer>
            <List sx={{ p: 0 }}>
              {globalPlaybackState.playlist.map((track, index) => (
                <React.Fragment key={track.id}>
                  <PlaylistItem 
                    isplaying={globalPlaybackState.isPlaying ? 'playing' : 'not-playing'}
                    current={globalPlaybackState.currentTrack?.id === track.id ? track.id : ''}
                    onClick={() => selectTrackFromPlaylist(track)}
                    sx={{
                      py: { xs: 1, sm: 1.5 },
                      px: { xs: 1, sm: 2 },
                    }}
                  >
                    <ListItemIcon sx={{ minWidth: { xs: 40, sm: 56 } }}>
                      {globalPlaybackState.currentTrack?.id === track.id && globalPlaybackState.isPlaying ? (
                        <MusicNoteIcon 
                          color="primary" 
                          sx={{ fontSize: { xs: 20, sm: 24 } }}
                        />
                      ) : (
                        <Typography 
                          variant="body2" 
                          color="text.secondary"
                          sx={{ fontSize: { xs: '0.875rem', sm: '1rem' } }}
                        >
                          {index + 1}
                        </Typography>
                      )}
                    </ListItemIcon>
                    <ListItemText
                      primary={
                        <Typography 
                          variant="body1" 
                          fontWeight={globalPlaybackState.currentTrack?.id === track.id ? 'bold' : 'normal'}
                          color={globalPlaybackState.currentTrack?.id === track.id ? 'primary.main' : 'text.primary'}
                          sx={{ 
                            fontSize: { xs: '0.9rem', sm: '1rem' },
                            pr: { xs: 4, sm: 6 },
                          }}
                          noWrap
                        >
                          {track.name}
                        </Typography>
                      }
                      secondary={
                        <Typography 
                          variant="body2" 
                          color="text.secondary"
                          sx={{ fontSize: { xs: '0.75rem', sm: '0.875rem' } }}
                        >
                          {track.category} • {audioFileInfo[track.id]?.duration ? formatTime(audioFileInfo[track.id].duration) : formatTime(track.duration || 0)}
                        </Typography>
                      }
                    />
                    <ListItemSecondaryAction>
                      <IconButton 
                        edge="end" 
                        onClick={(e) => {
                          e.stopPropagation()
                          selectTrackFromPlaylist(track)
                        }}
                        sx={{ 
                          color: globalPlaybackState.currentTrack?.id === track.id ? 'primary.main' : 'text.secondary',
                          p: { xs: 0.5, sm: 1 },
                        }}
                      >
                        <PlayArrowIcon sx={{ fontSize: { xs: 20, sm: 24 } }} />
                      </IconButton>
                    </ListItemSecondaryAction>
                  </PlaylistItem>
                </React.Fragment>
              ))}
            </List>
          </PlaylistContainer>
        </DialogContent>
        <DialogActions sx={{ p: { xs: 1.5, sm: 2 }, pt: 0 }}>
          <Button 
            onClick={() => {
              console.log('Closing playlist dialog')
              closePlaylistDialog()
            }}
            sx={{ fontSize: { xs: '0.875rem', sm: '1rem' } }}
          >
            返回列表
          </Button>
        </DialogActions>
      </Dialog>

      {/* 错误通知 */}
      <Snackbar
        open={!!error || notificationOpen}
        autoHideDuration={6000}
        onClose={handleCloseNotification}
      >
        <Alert onClose={handleCloseNotification} severity="error" sx={{ width: '100%' }}>
          {error || '操作失败'}
        </Alert>
      </Snackbar>

      {/* 隐藏的音频元素 */}
      <audio
        ref={audioRef}
        onTimeUpdate={handleTimeUpdate}
        onLoadedMetadata={handleLoadedMetadata}
        onEnded={handleEnded}
        onError={(e) => {
          console.error('音频元素错误:', e);
        }}
        onLoadStart={() => {
          console.log('开始加载音频');
        }}
        onCanPlay={() => {
          console.log('音频可以播放');
        }}
        preload="metadata"
      />

      {/* 音乐播放器对话框 */}
      <MusicPlayerDialog 
        open={musicPlayerDialogOpen}
        onClose={closeMusicPlayerDialog}
      />
    </Container>
  )
}

export default Music