/**
 * 检查文件是否存在
 * @param url 文件URL
 * @returns Promise<boolean> 文件是否存在
 */
export async function checkFileExists(url: string): Promise<boolean> {
  try {
    const response = await fetch(url, { method: 'HEAD' })
    return response.ok
  } catch (error) {
    return false
  }
}

/**
 * 创建MediaFile对象
 * @param fileName 文件名
 * @param directoryPath 目录路径
 * @param url 文件URL
 * @param type 媒体类型
 * @returns MediaFile对象
 */
export function createMediaFile(
  fileName: string,
  directoryPath: string,
  url: string,
  type: 'image' | 'video' | 'audio'
): MediaFile {
  const now = new Date()
  const id = `file-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`
  
  // 从文件名中提取扩展名
  const extension = fileName.split('.').pop()?.toLowerCase() || ''
  
  return {
    id,
    name: fileName,
    path: directoryPath,
    url,
    type,
    size: 0, // 在实际应用中应该获取真实文件大小
    format: extension,
    category: type,
    tags: [],
    createdAt: now,
    modifiedAt: now
  }
}

/**
 * 获取文件URL
 * @param directoryPath 目录路径
 * @param fileName 文件名
 * @returns 文件URL
 */
export function getFileUrl(directoryPath: string, fileName: string): string {
  // 使用路径验证工具获取正确的URL
  return getMediaFileUrl(directoryPath, fileName)
}