import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import {
  Container,
  Typography,
  Box,
  Paper,
  Button,
  Avatar,
  Chip,
  Divider,
  CircularProgress,
  Alert,
  Breadcrumbs,
  Link,
  IconButton,
  Tooltip,
  Menu,
  MenuItem,
} from '@mui/material';
import {
  ArrowBack,
  CalendarToday,
  Visibility,
  ThumbUp,
  Comment,
  Share,
  Bookmark,
  MoreVert,
  Edit,
  Delete,
} from '@mui/icons-material';
import { useSelector } from 'react-redux';
import { useGetBlogPostQuery } from '../../store/api/unifiedBlogApi';
import { RootState } from '../../store/index';
import Markdown from '../../components/blog/Markdown';
import { MarkdownStyleComponent } from '../../components/blog/Markdown';
import LazyImage from '../../components/blog/LazyImage';
import { usePermissionCheck } from '../../components/auth/ProtectedRoute';

const BlogPost = () => {
  const { slug } = useParams<{ slug: string }>();
  const navigate = useNavigate();
  const [likeCount, setLikeCount] = useState(0);
  const [isLiked, setIsLiked] = useState(false);
  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
  
  const { isAuthenticated } = useSelector((state: RootState) => state.auth);
  const { canEditResource, canDeleteResource } = usePermissionCheck();
  
  const { data: postResponse, error, isLoading } = useGetBlogPostQuery({ 
    slug, 
    source: 'local' 
  });
  
  const post = postResponse?.data;

  useEffect(() => {
    if (post) {
      setLikeCount(post.likeCount || 0);
      setIsLiked(false);
    }
  }, [post]);

  const goBack = () => {
    navigate('/blog');
  };

  const handleLike = async () => {
    if (!isAuthenticated) {
      navigate('/login');
      return;
    }

    if (!post) return;

    try {
      if (isLiked) {
        setLikeCount(prev => prev - 1);
        setIsLiked(false);
      } else {
        setLikeCount(prev => prev + 1);
        setIsLiked(true);
      }
    } catch (error) {
      console.error('点赞操作失败:', error);
    }
  };

  const handleShare = () => {
    if (navigator.share) {
      navigator.share({
        title: post?.title,
        text: post?.excerpt,
        url: window.location.href,
      });
    } else {
        navigator.clipboard.writeText(window.location.href);
      }
  };

  const handleMenuOpen = (event: React.MouseEvent<HTMLElement>) => {
    setAnchorEl(event.currentTarget);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
  };

  const handleEdit = () => {
    if (post) {
      navigate(`/blog/edit/${post.slug}`);
    }
    handleMenuClose();
  };

  const handleDelete = async () => {
    if (post && window.confirm('确定要删除这篇文章吗？此操作不可撤销。')) {
      try {
        console.log('删除文章:', post.id || post.slug);
        navigate('/blog');
      } catch (error) {
        console.error('删除文章失败:', error);
      }
    }
    handleMenuClose();
  };

  // 检查用户是否可以编辑或删除这篇文章
  const canEdit = post && canEditResource(post.author.id || '');
  const canDelete = post && canDeleteResource(post.author.id || '');

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleDateString('zh-CN', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  };

  if (isLoading) {
    return (
      <Container maxWidth="lg" sx={{ py: 4 }}>
        <Box sx={{ display: 'flex', justifyContent: 'center', py: 8 }}>
          <CircularProgress />
        </Box>
      </Container>
    );
  }

  if (error || !post) {
    return (
      <Container maxWidth="lg" sx={{ py: 4 }}>
        <Alert severity="error" sx={{ mb: 3 }}>
          {error ? `加载文章时出错: ${JSON.stringify(error)}` : '文章未找到'}
        </Alert>
        <Button variant="contained" onClick={goBack} startIcon={<ArrowBack />}>
          返回博客列表
        </Button>
      </Container>
    );
  }

  return (
    <>
      <MarkdownStyleComponent />
      <Container maxWidth="lg" sx={{ py: 4 }}>
        {/* 面包屑导航 */}
        <Breadcrumbs sx={{ mb: 2 }}>
          <Link color="inherit" href="/" onClick={(e) => { e.preventDefault(); navigate('/'); }}>
            首页
          </Link>
          <Link color="inherit" href="/blog" onClick={(e) => { e.preventDefault(); navigate('/blog'); }}>
            博客
          </Link>
          <Typography color="text.primary">{post.title}</Typography>
        </Breadcrumbs>

        {/* 返回按钮 */}
        <Button 
          variant="outlined" 
          startIcon={<ArrowBack />}
          onClick={goBack}
          sx={{ mb: 3 }}
        >
          返回博客列表
        </Button>

        <Paper sx={{ p: { xs: 2, md: 4 } }}>
          {/* 文章标题和元信息 */}
          <Box sx={{ mb: 4 }}>
            <Typography variant="h3" component="h1" gutterBottom sx={{ fontWeight: 'bold' }}>
              {post.title}
            </Typography>
            
            <Box sx={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: 2, mb: 2 }}>
              <Box sx={{ display: 'flex', alignItems: 'center' }}>
                <Avatar 
                  sx={{ width: 32, height: 32, mr: 1 }}
                  src={post.author.picture}
                  alt={post.author.name}
                >
                  {post.author.name.charAt(0)}
                </Avatar>
                <Typography variant="body1">
                  {post.author.name}
                </Typography>
              </Box>
              
              <Box sx={{ display: 'flex', alignItems: 'center', color: 'text.secondary' }}>
                <CalendarToday sx={{ fontSize: 18, mr: 0.5 }} />
                <Typography variant="body2">
                  {post.date ? formatDate(post.date) : (post.createdAt ? formatDate(post.createdAt) : '')}
                </Typography>
              </Box>
              
              {post.category && (
                <Chip 
                  label={post.category} 
                  size="small" 
                  color="primary" 
                  variant="outlined"
                />
              )}
            </Box>
            
            {post.tags && post.tags.length > 0 && (
              <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5, mb: 2 }}>
                {post.tags.map((tag) => (
                  <Chip key={tag} label={tag} size="small" variant="outlined" />
                ))}
              </Box>
            )}
            
            <Divider sx={{ mb: 2 }} />
            
            {/* 交互按钮 */}
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              <Tooltip title={isLiked ? "取消点赞" : "点赞"}>
                <IconButton 
                  onClick={handleLike}
                  color={isLiked ? "primary" : "default"}
                >
                  <ThumbUp />
                </IconButton>
              </Tooltip>
              <Typography variant="body2" sx={{ mr: 1 }}>
                {likeCount}
              </Typography>
              
              <Tooltip title="评论">
                <IconButton color="default">
                  <Comment />
                </IconButton>
              </Tooltip>
              <Typography variant="body2" sx={{ mr: 1 }}>
                {post.commentCount || 0}
              </Typography>
              
              <Tooltip title="浏览量">
                <Box sx={{ display: 'flex', alignItems: 'center' }}>
                  <Visibility sx={{ fontSize: 20, mr: 0.5 }} />
                  <Typography variant="body2">
                    {post.viewCount || 0}
                  </Typography>
                </Box>
              </Tooltip>
              
              <Box sx={{ flexGrow: 1 }} />
              
              {/* 编辑和删除菜单 - 仅当用户有权限时显示 */}
              {(canEdit || canDelete) && (
                <>
                  <Tooltip title="更多操作">
                    <IconButton onClick={handleMenuOpen}>
                      <MoreVert />
                    </IconButton>
                  </Tooltip>
                  <Menu
                    anchorEl={anchorEl}
                    open={Boolean(anchorEl)}
                    onClose={handleMenuClose}
                  >
                    {canEdit && (
                      <MenuItem onClick={handleEdit}>
                        <Edit sx={{ mr: 1 }} fontSize="small" />
                        编辑
                      </MenuItem>
                    )}
                    {canDelete && (
                      <MenuItem onClick={handleDelete}>
                        <Delete sx={{ mr: 1 }} fontSize="small" />
                        删除
                      </MenuItem>
                    )}
                  </Menu>
                </>
              )}
              
              <Tooltip title="分享">
                <IconButton onClick={handleShare}>
                  <Share />
                </IconButton>
              </Tooltip>
              
              {isAuthenticated && (
                <Tooltip title="收藏">
                  <IconButton>
                    <Bookmark />
                  </IconButton>
                </Tooltip>
              )}
            </Box>
          </Box>

          {/* 文章封面图 */}
          {post.coverImage && (
            <Box sx={{ mb: 4, borderRadius: 2, overflow: 'hidden' }}>
              <LazyImage 
                src={post.coverImage} 
                alt={post.title}
                style={{ 
                  width: '100%', 
                  maxHeight: 400,
                  objectFit: 'cover'
                }}
              />
            </Box>
          )}

          {/* 文章内容 */}
          <Box sx={{ mb: 4 }}>
            <Markdown content={post.content} />
          </Box>
          
          <Divider />
          
          {/* 文章底部信息 */}
          <Box sx={{ mt: 3, textAlign: 'center' }}>
            <Typography variant="body2" color="text.secondary">
              本文由 {post.author.name} 发布于 {post.date ? formatDate(post.date) : (post.createdAt ? formatDate(post.createdAt) : '')}
            </Typography>
            
            {post.tags && post.tags.length > 0 && (
              <Box sx={{ mt: 2, display: 'flex', justifyContent: 'center', flexWrap: 'wrap', gap: 0.5 }}>
                <Typography variant="body2" color="text.secondary" sx={{ mr: 1 }}>
                  标签:
                </Typography>
                {post.tags.map((tag) => (
                  <Chip 
                    key={tag} 
                    label={tag} 
                    size="small" 
                    variant="outlined"
                    component="a"
                    href={`/blog?tag=${encodeURIComponent(tag)}`}
                    clickable
                  />
                ))}
              </Box>
            )}
          </Box>
        </Paper>
      </Container>
    </>
  );
};

export default BlogPost;