// 辅助函数：根据文件扩展名获取媒体类型
export const getMediaTypeFromExtension = (filename: string): 'image' | 'video' | 'audio' | null => {
  const extension = filename.toLowerCase().substring(filename.lastIndexOf('.'))
  
  if (SUPPORTED_FILE_TYPES.images.includes(extension)) {
    return 'image'
  }
  
  if (SUPPORTED_FILE_TYPES.videos.includes(extension)) {
    return 'video'
  }
  
  if (SUPPORTED_FILE_TYPES.audios.includes(extension)) {
    return 'audio'
  }
  
  return null
}

// 辅助函数：获取文件类型图标
export const getFileTypeIcon = (type: string): string => {
  switch (type) {
    case 'image':
      return 'image'
    case 'video':
      return 'video_library'
    case 'audio':
      return 'music_note'
    default:
      return 'insert_drive_file'
  }
}

// 辅助函数：检查文件大小是否超过限制
export const isFileSizeValid = (file: File, type: 'image' | 'video' | 'audio'): boolean => {
  const maxSize = MAX_FILE_SIZE[`${type}s` as keyof typeof MAX_FILE_SIZE]
  return file.size <= maxSize
}

// 辅助函数：格式化文件大小
export const formatFileSize = (bytes: number): string => {
  if (bytes === 0) return '0 Bytes'
  
  const k = 1024
  const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB']
  const i = Math.floor(Math.log(bytes) / Math.log(k))
  
  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i]
}