import { createApi, fetchBaseQuery } from '@reduxjs/toolkit/query/react'
import type { RootState } from '../index'

export interface Essay {
  _id: string
  title: string
  slug: string
  content: string
  excerpt: string
  mood: string
  tags: string[]
  published: boolean
  views: number
  likes: number
  comments: string[]
  author: {
    id: string
    username: string
    avatar?: string
  }
  createdAt: string
  updatedAt: string
}

export interface EssaysResponse {
  success: boolean
  data: Essay[]
  pagination: {
    page: number
    limit: number
    total: number
    totalPages: number
  }
}

export interface EssayResponse {
  success: boolean
  data: Essay
}

export interface CreateEssayRequest {
  title: string
  content: string
  excerpt: string
  mood: string
  tags: string[]
  published?: boolean
}

export const essayApi = createApi({
  reducerPath: 'essayApi',
  baseQuery: fetchBaseQuery({
    baseUrl: '/api/v1/essays',
    prepareHeaders: (headers, { getState }) => {
      const token = (getState() as RootState).auth.token
      if (token) {
        headers.set('authorization', `Bearer ${token}`)
      }
      return headers
    },
  }),
  tagTypes: ['Essay'],
  endpoints: (builder) => ({
    getEssays: builder.query<EssaysResponse, { page?: number; limit?: number; mood?: string; tag?: string }>({
      query: ({ page = 1, limit = 10, mood, tag }) => {
        let queryParams = `?page=${page}&limit=${limit}`
        if (mood) queryParams += `&mood=${mood}`
        if (tag) queryParams += `&tag=${tag}`
        return queryParams
      },
      providesTags: ['Essay'],
    }),
    getEssay: builder.query<EssayResponse, string>({
      query: (id) => `/${id}`,
      providesTags: (_result, _error, id) => [{ type: 'Essay', id }],
    }),
    createEssay: builder.mutation<EssayResponse, CreateEssayRequest>({
      query: (essay) => ({
        url: '',
        method: 'POST',
        body: essay,
      }),
      invalidatesTags: ['Essay'],
    }),
    updateEssay: builder.mutation<EssayResponse, { id: string; data: Partial<CreateEssayRequest> }>({
      query: ({ id, data }) => ({
        url: `/${id}`,
        method: 'PUT',
        body: data,
      }),
      invalidatesTags: (_result, _error, { id }) => [{ type: 'Essay', id }],
    }),
    deleteEssay: builder.mutation<void, string>({
      query: (id) => ({
        url: `/${id}`,
        method: 'DELETE',
      }),
      invalidatesTags: ['Essay'],
    }),
    likeEssay: builder.mutation<EssayResponse, string>({
      query: (id) => ({
        url: `/${id}/like`,
        method: 'POST',
      }),
      invalidatesTags: (_result, _error, id) => [{ type: 'Essay', id }],
    }),
  }),
})

export const {
  useGetEssaysQuery,
  useGetEssayQuery,
  useCreateEssayMutation,
  useUpdateEssayMutation,
  useDeleteEssayMutation,
  useLikeEssayMutation,
} = essayApi