import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import {
  Container,
  Typography,
  Box,
  Paper,
  Grid,
  CircularProgress,
  Alert,
  Pagination,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  ToggleButton,
  ToggleButtonGroup,
  Fab,
  Zoom,
} from '@mui/material';
import {
  Add,
  ViewList,
  ViewModule,
} from '@mui/icons-material';
import { useGetBlogPostsQuery } from '../../store/api/unifiedBlogApi';
import ArticleCard from '../../components/blog/ArticleCard';
import { MarkdownStyleComponent } from '../../components/blog/Markdown';
import { ConditionalRender } from '../../components/auth/ProtectedRoute';
import { Permission } from '../../utils/permissions.tsx';

// 分类选项
const categories = ['全部', '前端开发', '后端开发', '移动开发', '数据库', '人工智能', '未分类'];
const sortOptions = ['最新发布', '最多浏览', '最多点赞'];

const Blog = () => {
  const [page, setPage] = useState(1);
  const [category, setCategory] = useState('全部');
  const [sortBy, setSortBy] = useState('最新发布');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [dataSource, setDataSource] = useState<'local' | 'remote' | 'all'>('local');
  
  const postsPerPage = 6;

  // 使用统一的博客API获取数据
  const { data: blogData, error, isLoading } = useGetBlogPostsQuery({
    page,
    limit: postsPerPage,
    category: category === '全部' ? undefined : category,
    source: dataSource
  });

  const posts = blogData?.data || [];
  const pagination = blogData?.pagination;

  // 添加调试日志
  useEffect(() => {
    console.log('Blog组件 - 博客数据:', blogData);
    console.log('Blog组件 - 加载状态:', isLoading);
    console.log('Blog组件 - 文章列表:', posts);
    console.log('Blog组件 - 数据源:', dataSource);
  }, [blogData, isLoading, posts, dataSource]);

  const handlePageChange = (_event: React.ChangeEvent<unknown>, value: number) => {
    setPage(value);
  };

  const handleCategoryChange = (event: any) => {
    setCategory(event.target.value);
    setPage(1);
  };

  const handleSortChange = (event: any) => {
    setSortBy(event.target.value);
    setPage(1);
  };

  const handleViewModeChange = (
    _event: React.MouseEvent<HTMLElement>,
    nextViewMode: 'grid' | 'list' | null,
  ) => {
    if (nextViewMode !== null) {
      setViewMode(nextViewMode);
    }
  };

  const handleDataSourceChange = (
    _event: React.MouseEvent<HTMLElement>,
    nextDataSource: 'local' | 'remote' | 'all' | null,
  ) => {
    if (nextDataSource !== null) {
      setDataSource(nextDataSource);
      setPage(1);
    }
  };

  // 获取英雄文章（第一篇文章）
  const heroPost = posts.length > 0 ? posts[0] : null;
  const morePosts = posts.length > 1 ? posts.slice(1) : [];

  return (
    <>
      <MarkdownStyleComponent />
      <Container maxWidth="lg" sx={{ py: 4 }}>
        <Box sx={{ mb: 4 }}>
          <Typography variant="h3" component="h1" gutterBottom>
            知识博客
          </Typography>
          <Typography variant="h6" color="text.secondary">
            分享技术知识，记录学习心得
          </Typography>
        </Box>

        {/* 数据源选择 */}
        <Paper sx={{ p: 2, mb: 3 }}>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 2 }}>
            <ToggleButtonGroup
              value={dataSource}
              exclusive
              onChange={handleDataSourceChange}
              aria-label="数据源"
              size="small"
            >
              <ToggleButton value="local" aria-label="本地文章">
                本地文章
              </ToggleButton>
              <ToggleButton value="remote" aria-label="远程文章">
                远程文章
              </ToggleButton>
              <ToggleButton value="all" aria-label="所有文章">
                所有文章
              </ToggleButton>
            </ToggleButtonGroup>

            <ToggleButtonGroup
              value={viewMode}
              exclusive
              onChange={handleViewModeChange}
              aria-label="视图模式"
              size="small"
            >
              <ToggleButton value="grid" aria-label="网格视图">
                <ViewModule />
              </ToggleButton>
              <ToggleButton value="list" aria-label="列表视图">
                <ViewList />
              </ToggleButton>
            </ToggleButtonGroup>
          </Box>
        </Paper>

        {/* 筛选和排序 */}
        <Paper sx={{ p: 2, mb: 3 }}>
          <Grid container spacing={2} alignItems="center">
            <Grid size={{ xs: 12, sm: 6, md: 3 }}>
              <FormControl fullWidth variant="outlined" size="small">
                <InputLabel>分类</InputLabel>
                <Select
                  value={category}
                  onChange={handleCategoryChange}
                  label="分类"
                >
                  {categories.map((cat) => (
                    <MenuItem key={cat} value={cat}>
                      {cat}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid size={{ xs: 12, sm: 6, md: 3 }}>
              <FormControl fullWidth variant="outlined" size="small">
                <InputLabel>排序</InputLabel>
                <Select
                  value={sortBy}
                  onChange={handleSortChange}
                  label="排序"
                >
                  {sortOptions.map((option) => (
                    <MenuItem key={option} value={option}>
                      {option}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
          </Grid>
        </Paper>

        {isLoading ? (
          <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
            <CircularProgress />
          </Box>
        ) : error ? (
          <Alert severity="error" sx={{ mb: 3 }}>
            加载博客文章时出错: {JSON.stringify(error)}
          </Alert>
        ) : (
          <>
            {/* 精选文章 */}
            {heroPost && viewMode === 'grid' && (
              <Box sx={{ mb: 4 }}>
                <Typography variant="h4" component="h2" gutterBottom sx={{ fontWeight: 'bold' }}>
                  精选文章
                </Typography>
                <ArticleCard post={heroPost} featured={true} />
              </Box>
            )}

            {/* 更多文章 */}
            {morePosts.length > 0 && (
              <Box>
                {viewMode === 'grid' && (
                  <Typography variant="h4" component="h2" gutterBottom sx={{ fontWeight: 'bold', mb: 3 }}>
                    更多文章
                  </Typography>
                )}
                
                <Grid container spacing={3}>
                  {(viewMode === 'grid' ? morePosts : posts).map((post) => (
                    <Grid size={{ xs: 12, md: viewMode === 'grid' ? 6 : 12 }} key={post.slug}>
                      <ArticleCard post={post} featured={false} />
                    </Grid>
                  ))}
                </Grid>
              </Box>
            )}

            {/* 分页 */}
            {pagination && pagination.totalPages > 1 && (
              <Box sx={{ display: 'flex', justifyContent: 'center', mt: 4 }}>
                <Pagination
                  count={pagination.totalPages}
                  page={page}
                  onChange={handlePageChange}
                  color="primary"
                />
              </Box>
            )}
          </>
        )}

        {/* 写文章按钮 */}
        <ConditionalRender requiredPermission={Permission.WRITE_BLOG}>
          <Zoom in={true}>
            <Fab
              color="primary"
              aria-label="写文章"
              component={Link}
              to="/blog/create"
              sx={{
                position: 'fixed',
                bottom: 16,
                right: 16,
                zIndex: 1000,
              }}
            >
              <Add />
            </Fab>
          </Zoom>
        </ConditionalRender>
      </Container>
    </>
  );
};

export default Blog;