import { createApi, fetchBaseQuery } from '@reduxjs/toolkit/query/react'
import type { RootState } from '../index'

export interface Media {
  _id: string
  title: string
  description: string
  type: 'image' | 'video' | 'audio'
  url: string
  thumbnail?: string
  duration?: number
  size: number
  tags: string[]
  category: string
  featured: boolean
  views: number
  likes: number
  comments: string[]
  author: {
    id: string
    username: string
    avatar?: string
  }
  createdAt: string
  updatedAt: string
}

export interface MediaResponse {
  success: boolean
  data: Media[]
  pagination: {
    page: number
    limit: number
    total: number
    totalPages: number
  }
}

export interface SingleMediaResponse {
  success: boolean
  data: Media
}

export interface CreateMediaRequest {
  title: string
  description: string
  type: 'image' | 'video' | 'audio'
  url: string
  thumbnail?: string
  duration?: number
  size: number
  tags: string[]
  category: string
  featured?: boolean
}

export const mediaApi = createApi({
  reducerPath: 'mediaApi',
  baseQuery: fetchBaseQuery({
    baseUrl: '/api/v1/media',
    prepareHeaders: (headers, { getState }) => {
      const token = (getState() as RootState).auth.token
      if (token) {
        headers.set('authorization', `Bearer ${token}`)
      }
      return headers
    },
  }),
  tagTypes: ['Media'],
  endpoints: (builder) => ({
    getMedia: builder.query<MediaResponse, { page?: number; limit?: number; type?: string; category?: string; tag?: string }>({
      query: ({ page = 1, limit = 12, type, category, tag }) => {
        let queryParams = `?page=${page}&limit=${limit}`
        if (type) queryParams += `&type=${type}`
        if (category) queryParams += `&category=${category}`
        if (tag) queryParams += `&tag=${tag}`
        return queryParams
      },
      providesTags: ['Media'],
    }),
    getSingleMedia: builder.query<SingleMediaResponse, string>({
      query: (id) => `/${id}`,
      providesTags: (_result, _error, id) => [{ type: 'Media', id }],
    }),
    createMedia: builder.mutation<SingleMediaResponse, CreateMediaRequest>({
      query: (media) => ({
        url: '',
        method: 'POST',
        body: media,
      }),
      invalidatesTags: ['Media'],
    }),
    updateMedia: builder.mutation<SingleMediaResponse, { id: string; data: Partial<CreateMediaRequest> }>({
      query: ({ id, data }) => ({
        url: `/${id}`,
        method: 'PUT',
        body: data,
      }),
      invalidatesTags: (_result, _error, { id }) => [{ type: 'Media', id }],
    }),
    deleteMedia: builder.mutation<void, string>({
      query: (id) => ({
        url: `/${id}`,
        method: 'DELETE',
      }),
      invalidatesTags: ['Media'],
    }),
    likeMedia: builder.mutation<SingleMediaResponse, string>({
      query: (id) => ({
        url: `/${id}/like`,
        method: 'POST',
      }),
      invalidatesTags: (_result, _error, id) => [{ type: 'Media', id }],
    }),
    getFeaturedMedia: builder.query<MediaResponse, void>({
      query: () => '/featured',
      providesTags: ['Media'],
    }),
  }),
})

export const {
  useGetMediaQuery,
  useGetSingleMediaQuery,
  useCreateMediaMutation,
  useUpdateMediaMutation,
  useDeleteMediaMutation,
  useLikeMediaMutation,
  useGetFeaturedMediaQuery,
} = mediaApi